# ─── Global Jinja2 date filter: DD-Mon-YYYY (e.g. 15-Apr-2026) ───
@app.template_filter('format_date')
def format_date_filter(value):
    """Convert a date string or date object to DD-Mon-YYYY format."""
    if not value:
        return '—'
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return '—'
        for fmt in ('%Y-%m-%d', '%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S',
                    '%d-%b-%Y', '%d/%m/%Y', '%d-%m-%Y'):
            try:
                value = datetime.strptime(value, fmt)
                break
            except ValueError:
                continue
        else:
            return value  # return as-is if no format matched
    try:
        return value.strftime('%d-%b-%Y')
    except (AttributeError, ValueError):
        return value

@app.template_filter('format_reg')
def format_reg_filter(value):
    """Normalize registration number to GCUKIP/YY-YY/NNN format.
    Converts GCUKIP/2022/042 → GCUKIP/22-23/042
    Leaves GCUKIP/22-23/042 or GCUKIP/25-26/009 as-is.
    """
    if not value or not isinstance(value, str):
        return value or '—'
    value = value.strip()
    if not value:
        return '—'
    import re as _re
    # Match GCUKIP/YYYY/NNN (4-digit year)
    m = _re.match(r'^(GCUKIP)/(\d{4})/(\d+)$', value)
    if m:
        prefix, year_str, num = m.group(1), m.group(2), m.group(3)
        year = int(year_str)
        yy = year % 100
        next_yy = (yy + 1) % 100
        return f"{prefix}/{yy:02d}-{next_yy:02d}/{num}"
    # Already in YY-YY format or other — return as-is
    return value


