@app.route('/calendar')
@login_required
def calendar_view():
    user = get_user()
    year = int(request.args.get('year', datetime.now().year))
    month = int(request.args.get('month', datetime.now().month))

    # Get calendar days
    month_days = calendar.monthcalendar(year, month)
    month_name = calendar.month_name[month]

    # Get holidays and leaves
    holidays = get_all_holidays()
    leaves = get_leaves_for_month(user['id'], year, month)
    leave_dates = {}
    for leave in leaves:
        if leave['leave_date'] not in leave_dates:
            leave_dates[leave['leave_date']] = []
        leave_dates[leave['leave_date']].append(leave)

    # Navigation
    prev_month = month - 1
    prev_year = year
    if prev_month < 1:
        prev_month = 12
        prev_year -= 1

    next_month = month + 1
    next_year = year
    if next_month > 12:
        next_month = 1
        next_year += 1

    today = datetime.now().strftime('%Y-%m-%d')

    return render_template('employee_calendar.html',
                         user=user,
                         year=year,
                         month=month,
                         month_name=month_name,
                         month_days=month_days,
                         holidays=holidays,
                         leave_dates=leave_dates,
                         prev_month=prev_month,
                         prev_year=prev_year,
                         next_month=next_month,
                         next_year=next_year,
                         today=today,
                    active_section='company')

