@app.route('/admin/calendar')
@admin_required
def admin_calendar():
    user = get_user()
    year = int(request.args.get('year', datetime.now().year))
    month = int(request.args.get('month', datetime.now().month))

    # Get calendar days
    month_days = calendar.monthcalendar(year, month)
    month_name = calendar.month_name[month]

    # Get all employees
    conn = get_db()
    employees = conn.execute("SELECT id, name FROM employees WHERE is_active = 1 AND emp_code != 'admin' ORDER BY name").fetchall()

    # Get all leaves for the month
    all_leaves = conn.execute('''
        SELECT lr.*, e.name, e.emp_code FROM leave_records lr
        JOIN employees e ON lr.employee_id = e.id
        WHERE lr.status = 'approved'
        AND strftime('%Y', lr.leave_date) = ? AND strftime('%m', lr.leave_date) = ?
        ORDER BY lr.leave_date, e.name
    ''', (str(year), str(month).zfill(2))).fetchall()

    conn.close()

    # Organize leaves by date
    leave_dates = {}
    for leave in all_leaves:
        if leave['leave_date'] not in leave_dates:
            leave_dates[leave['leave_date']] = []
        leave_dates[leave['leave_date']].append(leave)

    # Get holidays
    holidays = get_all_holidays()

    # Navigation
    prev_month = month - 1
    prev_year = year
    if prev_month < 1:
        prev_month = 12
        prev_year -= 1

    next_month = month + 1
    next_year = year
    if next_month > 12:
        next_month = 1
        next_year += 1

    today = datetime.now().strftime('%Y-%m-%d')

    return render_template('admin_calendar.html',
                         user=user,
                         year=year,
                         month=month,
                         month_name=month_name,
                         month_days=month_days,
                         holidays=holidays,
                         leave_dates=leave_dates,
                         employees=employees,
                         prev_month=prev_month,
                         prev_year=prev_year,
                         next_month=next_month,
                         next_year=next_year,
                         today=today,
                    active_section='company')

@app.route('/admin/employee/<int:emp_id>')
@admin_required
def admin_employee_detail(emp_id):
    user = get_user()
    conn = get_db()

    employee = conn.execute('SELECT * FROM employees WHERE id = ?', (emp_id,)).fetchone()
    if not employee:
        flash('Employee not found', 'error')
        conn.close()
        return redirect(url_for('admin_dashboard'))

    leaves_raw = conn.execute('''
        SELECT *, leave_group_id FROM leave_records
        WHERE employee_id = ?
        ORDER BY leave_date DESC
    ''', (emp_id,)).fetchall()

    # Group by leave_group_id
    from collections import OrderedDict
    leave_groups = OrderedDict()
    for r in leaves_raw:
        d = dict(r)
        gid = d.get('leave_group_id') or f"single_{d['id']}"
        if gid not in leave_groups:
            leave_groups[gid] = {
                **d,
                'group_id': gid,
                'group_ids': [d['id']],
                'group_total_days': d['days'],
                'group_count': 1,
                'date_from': d['leave_date'],
                'date_to': d['leave_date'],
            }
        else:
            g = leave_groups[gid]
            g['group_ids'].append(d['id'])
            g['group_total_days'] += d['days']
            g['group_count'] += 1
            if d['leave_date'] < g['date_from']:
                g['date_from'] = d['leave_date']
            if d['leave_date'] > g['date_to']:
                g['date_to'] = d['leave_date']
    leaves = list(leave_groups.values())

    # Calculate balance
    emp_data = conn.execute('SELECT carry_forward FROM employees WHERE id = ?', (emp_id,)).fetchone()
    carry_forward = emp_data['carry_forward'] if emp_data else 0
    total_allocation = 25 + carry_forward

    approved_leaves = conn.execute('''
        SELECT SUM(days) as total_days FROM leave_records
        WHERE employee_id = ? AND status = 'approved'
    ''', (emp_id,)).fetchone()

    days_taken = approved_leaves['total_days'] if approved_leaves['total_days'] else 0
    available = total_allocation - days_taken

    conn.close()

    return render_template('admin_employee_detail.html',
                         user=user,
                         employee=employee,
                         leaves=leaves,
                         total_allocation=total_allocation,
                         days_taken=days_taken,
                         available_balance=max(0, available),
                    active_section='hr')

