@app.route('/admin/pending-approvals')
@login_required
def pending_approvals():
    user = get_user()
    conn = get_db()

    # Filters
    f_employee = (request.args.get('employee') or '').strip()
    f_department = (request.args.get('department') or '').strip()
    f_type = (request.args.get('leave_type') or '').strip()
    active_tab = request.args.get('tab', 'pending')

    base_select = '''
        SELECT lr.id, lr.employee_id, lr.leave_type, lr.leave_date, lr.days,
               lr.day_portion, lr.reason, lr.status, lr.is_late,
               lr.original_id, lr.modification_reason, lr.original_reason,
               lr.approved_by, lr.approved_at, lr.created_at,
               lr.leave_group_id,
               e.name        AS employee_name,
               e.emp_code    AS emp_code,
               e.department  AS department,
               e.designation AS designation,
               e.email       AS email,
               e.phone       AS mobile,
               e.photo_url   AS photo_url,
               e.late_leave_count AS late_leave_count,
               COALESCE(approver.name, '') AS approver_name
        FROM leave_records lr
        JOIN employees e ON lr.employee_id = e.id
        LEFT JOIN employees approver ON lr.approved_by = approver.id
    '''

    def _build_where(status_filter):
        where = [status_filter]
        params = []
        # Role-based access: admin sees all, manager sees self + reports, employee sees own
        if user['is_admin']:
            pass  # no filter
        else:
            # Check if user has any reports
            has_reports = conn.execute('SELECT 1 FROM employees WHERE reporting_to = ? LIMIT 1', (user['id'],)).fetchone()
            if has_reports:
                # Manager: own + direct reports
                where.append('(e.id = ? OR e.reporting_to = ?)')
                params.extend([user['id'], user['id']])
            else:
                # Employee: own only
                where.append('e.id = ?')
                params.append(user['id'])
        if f_employee:
            where.append('(LOWER(e.name) LIKE ? OR LOWER(e.emp_code) LIKE ?)')
            like = f'%{f_employee.lower()}%'
            params.extend([like, like])
        if f_department:
            where.append('LOWER(e.department) LIKE ?')
            params.append(f'%{f_department.lower()}%')
        if f_type:
            where.append('lr.leave_type = ?')
            params.append(f_type)
        return where, params

    def _enrich(rows):
        result = []
        for r in rows:
            d = dict(r)
            p = d.get('photo_url') or ''
            d['photo_src'] = (p if p.startswith('http') else f'/static/photos/{p}') if p else ''
            raw = d.get('reason') or ''
            if '[Late Application Reason]:' in raw:
                parts = raw.split('\n\n[Late Application Reason]:', 1)
                d['reason_main'] = parts[0].strip()
                d['late_reason'] = parts[1].strip() if len(parts) > 1 else ''
            else:
                d['reason_main'] = raw
                d['late_reason'] = ''
            result.append(d)
        return result

    def _group_leaves(rows):
        """Group leave records by leave_group_id. Returns list of grouped dicts."""
        from collections import OrderedDict
        groups = OrderedDict()
        for r in rows:
            gid = r.get('leave_group_id') or f"single_{r['id']}"
            if gid not in groups:
                groups[gid] = {
                    **r,
                    'group_id': gid,
                    'group_ids': [r['id']],
                    'group_dates': [r['leave_date']],
                    'group_total_days': r['days'],
                    'group_count': 1,
                    'date_from': r['leave_date'],
                    'date_to': r['leave_date'],
                }
            else:
                g = groups[gid]
                g['group_ids'].append(r['id'])
                g['group_dates'].append(r['leave_date'])
                g['group_total_days'] += r['days']
                g['group_count'] += 1
                if r['leave_date'] < g['date_from']:
                    g['date_from'] = r['leave_date']
                if r['leave_date'] > g['date_to']:
                    g['date_to'] = r['leave_date']
        return list(groups.values())

    # Pending leaves
    pw, pp = _build_where("lr.status = 'pending'")
    pending_sql = base_select + ' WHERE ' + ' AND '.join(pw) + ' ORDER BY lr.is_late DESC, lr.created_at DESC'
    pending_raw = _enrich(conn.execute(pending_sql, tuple(pp)).fetchall())
    pending = _group_leaves(pending_raw)

    # Approved / Rejected leaves
    aw, ap = _build_where("lr.status IN ('approved', 'rejected')")
    approved_sql = base_select + ' WHERE ' + ' AND '.join(aw) + ' ORDER BY lr.approved_at DESC, lr.created_at DESC'
    approved_raw = _enrich(conn.execute(approved_sql, tuple(ap)).fetchall())
    approved = _group_leaves(approved_raw)

    # Late leave summary
    if user['is_admin']:
        late_summary = conn.execute('''
            SELECT name, emp_code, late_leave_count FROM employees
            WHERE late_leave_count > 0 AND is_active = 1 AND emp_code != 'admin'
            ORDER BY late_leave_count DESC
        ''').fetchall()
    else:
        late_summary = conn.execute('''
            SELECT name, emp_code, late_leave_count FROM employees
            WHERE late_leave_count > 0 AND reporting_to = ? AND is_active = 1
            ORDER BY late_leave_count DESC
        ''', (user['id'],)).fetchall()

    total_count = len(pending)
    late_count = sum(1 for p in pending if p.get('is_late'))
    reapproval_count = sum(1 for p in pending if p.get('original_id'))
    approved_count = sum(1 for a in approved if a.get('status') == 'approved')
    rejected_count = sum(1 for a in approved if a.get('status') == 'rejected')

    conn.close()

    return render_template('pending_approvals.html', user=user,
                         pending_leaves=pending, approved_leaves=approved,
                         late_leave_summary=late_summary,
                         f_employee=f_employee, f_department=f_department, f_type=f_type,
                         active_tab=active_tab,
                         total_count=total_count, late_count=late_count,
                         reapproval_count=reapproval_count,
                         approved_count=approved_count, rejected_count=rejected_count,
                    active_section='hr')

@app.route('/admin/approve-leave/<int:leave_id>', methods=['POST'])
@login_required
def approve_leave(leave_id):
    user = get_user()
    conn = get_db()

    leave = conn.execute('SELECT * FROM leave_records WHERE id = ?', (leave_id,)).fetchone()
    if not leave:
        flash('Leave not found', 'error')
        conn.close()
        return redirect(url_for('pending_approvals'))

    leave_emp = conn.execute('SELECT * FROM employees WHERE id = ?', (leave['employee_id'],)).fetchone()
    allowed, reason = can_approve_leave(user, leave_emp, conn)
    if not allowed:
        flash(reason, 'error')
        conn.close()
        return redirect(url_for('pending_approvals'))

    conn.execute('''
        UPDATE leave_records
        SET status = 'approved', approved_by = ?, approved_at = ?
        WHERE id = ?
    ''', (user['id'], datetime.now().strftime('%Y-%m-%d %H:%M:%S'), leave_id))
    # Notify employee
    create_notification(conn, leave['employee_id'],
        'Leave Approved',
        f'Your {leave["leave_type"]} leave on {leave["leave_date"]} has been approved by {user["name"]}.',
        'success', '/my-leaves')
    # Capture values before closing connection
    emp_name = leave_emp['name'] if leave_emp else None
    emp_email = leave_emp['email'] if leave_emp else None
    l_type = leave['leave_type']
    l_date = leave['leave_date']
    approver = user['name']
    conn.commit()
    conn.close()

    # Send approval email
    if emp_email:
        send_leave_status_email(emp_name, emp_email, l_type, l_date, 'approved', approver)

    flash('Leave approved', 'success')
    return redirect(request.referrer or url_for('pending_approvals'))

