def get_lookup_options(category):
    """Fetch active lookup options for a category from the database."""
    try:
        conn = get_db()
        rows = conn.execute(
            "SELECT value FROM lookup_options WHERE category = ? AND is_active = TRUE ORDER BY sort_order, id",
            (category,)
        ).fetchall()
        conn.close()
        return [r['value'] for r in rows]
    except Exception as e:
        logging.error(f"get_lookup_options({category}): {e}")
        return []


def _next_registration_number(conn):
    """Generate next GCUKIP/YY-YY/NNN registration number."""
    now = datetime.now()
    if now.month >= 4:
        y1, y2 = now.year % 100, (now.year + 1) % 100
    else:
        y1, y2 = (now.year - 1) % 100, now.year % 100
    prefix = f"GCUKIP/{y1:02d}-{y2:02d}/"
    row = conn.execute(
        "SELECT registration_number FROM plab_clients WHERE registration_number LIKE ? ORDER BY registration_number DESC LIMIT 1",
        (prefix + '%',)
    ).fetchone()
    if row:
        try:
            last_num = int(row['registration_number'].split('/')[-1])
        except (ValueError, IndexError):
            last_num = 0
    else:
        last_num = 0
    return f"{prefix}{last_num + 1:03d}"


