VENDOR_CATEGORIES = ['Training Programs', 'Online Courses', 'Research & Publications', 'NGO Activities', 'Certification Bodies', 'Online Subscriptions']

# Hard-coded vendor map used as inline data in coaching form (no AJAX needed)
VENDOR_SERVICE_MAP = {
    'IELTS Training': ['Verbis', 'Britford Training Academy', 'Other'],
    'OET Training': ['Verbis', 'Britford Training Academy', 'Other'],
    'PLAB 1 Training': ['ABMA', 'Arora PLAB 1', 'Other'],
    'PLAB 2 Training': ['Aspire Academy', 'ABMA & Aspire', 'Arora PLAB 2', 'Other'],
    'PLAB 2 Mock': ['Aspire Academy', 'ABMA & Aspire', 'Other'],
    'MRCP 1': ['Other'],
}

# ── Vendor ↔ lookup_options sync mapping ──
# Maps lookup_options category → how to query vendors_providers
# 'service'      = filter by vendor_service_map.service_name → vendor names become dropdown values
# 'category'     = filter by vendors_providers.category → vendor names become dropdown values
# 'deliverables' = collect all service_names from vendor_service_map for vendors in a category
VENDOR_LOOKUP_MAP = {
    'ielts_vendor':      {'type': 'service',  'service': 'IELTS Training',  'country': 'UK Pathway'},
    'oet_vendor':        {'type': 'service',  'service': 'OET Training',    'country': 'UK Pathway'},
    'plab1_partner':     {'type': 'service',  'service': 'PLAB 1 Training', 'country': 'UK Pathway'},
    'research_provider': {'type': 'category', 'category': 'Research & Publications', 'country': 'UK Pathway'},
    'ngo_vendor':        {'type': 'category', 'category': 'NGO Activities', 'country': 'UK Pathway'},
    'plab2_vendor':      {'type': 'service',  'service': 'PLAB 2 Training', 'country': 'UK Pathway'},
    'certification_body': {'type': 'category', 'category': 'Certification Bodies', 'country': 'UK Pathway'},
    'course_provider':   {'type': 'category', 'category': 'Online Courses',  'country': 'UK Pathway'},
    'subscription_type': {'type': 'category', 'category': 'Online Subscriptions', 'country': 'UK Pathway'},
    'course_name':       {'type': 'deliverables', 'category': 'Online Courses', 'country': 'UK Pathway'},
}


def sync_vendors_to_lookup_options(conn=None):
    """Sync vendors_providers → lookup_options for vendor-linked categories.
    Additive only: adds missing options and deactivates removed vendors, never deletes data.
    """
    should_close = False
    if conn is None:
        conn = get_db()
        should_close = True
    try:
        for lo_category, vlink in VENDOR_LOOKUP_MAP.items():
            # Fetch active vendor names for this mapping
            country = vlink.get('country', 'UK Pathway')
            if vlink['type'] == 'service':
                vendor_rows = conn.execute("""
                    SELECT DISTINCT vp.name FROM vendors_providers vp
                    JOIN vendor_service_map vsm ON vp.id = vsm.vendor_id
                    WHERE vsm.service_name = ? AND vp.country = ? AND vp.is_active = TRUE
                    ORDER BY vp.sort_order, vp.name
                """, (vlink['service'], country)).fetchall()
            elif vlink['type'] == 'deliverables':
                # Collect all unique service_names from vendors in this category
                cat_pattern = '%' + vlink['category'] + '%'
                vendor_rows = conn.execute("""
                    SELECT DISTINCT vsm.service_name as name
                    FROM vendor_service_map vsm
                    JOIN vendors_providers vp ON vsm.vendor_id = vp.id
                    WHERE vp.category LIKE ? AND vp.country = ? AND vp.is_active = TRUE
                    ORDER BY vsm.service_name
                """, (cat_pattern, country)).fetchall()
            else:
                cat_pattern = '%' + vlink['category'] + '%'
                vendor_rows = conn.execute("""
                    SELECT name FROM vendors_providers
                    WHERE category LIKE ? AND country = ? AND is_active = TRUE
                    ORDER BY sort_order, name
                """, (cat_pattern, country)).fetchall()

            vendor_names = [r['name'] for r in vendor_rows]

            # Fetch existing lookup_options for this category
            existing = conn.execute(
                "SELECT id, value, is_active FROM lookup_options WHERE category = ? ORDER BY sort_order",
                (lo_category,)
            ).fetchall()
            existing_values = {r['value']: r for r in existing}

            # Get current max sort_order
            max_so = conn.execute(
                "SELECT COALESCE(MAX(sort_order), 0) as m FROM lookup_options WHERE category = ?",
                (lo_category,)
            ).fetchone()['m']

            # Add vendor names not yet in lookup_options
            for vname in vendor_names:
                if vname not in existing_values:
                    max_so += 1
                    conn.execute(
                        "INSERT INTO lookup_options (category, label, value, sort_order, is_active) VALUES (?, ?, ?, ?, TRUE)",
                        (lo_category, vname, vname, max_so)
                    )
                    logging.info(f"Vendor sync: added '{vname}' to lookup_options.{lo_category}")
                elif not existing_values[vname]['is_active']:
                    # Re-activate if vendor is active but lookup was deactivated
                    conn.execute(
                        "UPDATE lookup_options SET is_active = TRUE WHERE id = ?",
                        (existing_values[vname]['id'],)
                    )
                    logging.info(f"Vendor sync: re-activated '{vname}' in lookup_options.{lo_category}")

            # Deactivate lookup_options whose vendor is no longer active (but don't delete)
            for val, row in existing_values.items():
                if val not in vendor_names and row['is_active'] and val != 'Other':
                    # Check if this vendor exists but is inactive
                    inactive_check = conn.execute(
                        "SELECT id FROM vendors_providers WHERE name = ? AND is_active = FALSE LIMIT 1",
                        (val,)
                    ).fetchone()
                    if inactive_check:
                        conn.execute(
                            "UPDATE lookup_options SET is_active = FALSE WHERE id = ?",
                            (row['id'],)
                        )
                        logging.info(f"Vendor sync: deactivated '{val}' in lookup_options.{lo_category} (vendor inactive)")

        conn.commit()
        logging.info("Vendor ↔ lookup_options sync completed")
    except Exception as e:
        logging.error(f"sync_vendors_to_lookup_options error: {e}")
    finally:
        if should_close:
            conn.close()


def _build_vendor_map():
    """Build vendor map from DB, falling back to hard-coded map."""
    try:
        conn = get_db()
        rows = conn.execute("""
            SELECT vsm.service_name, vp.name
            FROM vendor_service_map vsm
            JOIN vendors_providers vp ON vsm.vendor_id = vp.id
            WHERE vp.is_active = TRUE AND vp.country = 'UK Pathway'
            ORDER BY vp.sort_order, vp.name
        """).fetchall()
        conn.close()
        if rows:
            vm = {}
            for r in rows:
                vm.setdefault(r['service_name'], []).append(r['name'])
            return vm
    except Exception as e:
        logging.error(f"_build_vendor_map DB error: {e}")
    # Fallback to hard-coded map
    return VENDOR_SERVICE_MAP


def get_vendors_for_service(service_name, country=None):
    """Return active vendors that provide a specific service (training/course/research name)."""
    conn = get_db()
    if country:
        rows = conn.execute("""
            SELECT DISTINCT vp.id, vp.name FROM vendors_providers vp
            JOIN vendor_service_map vsm ON vp.id = vsm.vendor_id
            WHERE vsm.service_name = ? AND vp.country = ? AND vp.is_active = TRUE
            ORDER BY vp.sort_order, vp.name
        """, (service_name, country)).fetchall()
    else:
        rows = conn.execute("""
            SELECT DISTINCT vp.id, vp.name FROM vendors_providers vp
            JOIN vendor_service_map vsm ON vp.id = vsm.vendor_id
            WHERE vsm.service_name = ? AND vp.is_active = TRUE
            ORDER BY vp.sort_order, vp.name
        """, (service_name,)).fetchall()
    conn.close()
    return [dict(r) for r in rows]


def get_vendors_by_category(category, country=None):
    """Return active vendors for a category (supports multi-category comma-separated values)."""
    conn = get_db()
    cat_pattern = '%' + category + '%'
    if country:
        rows = conn.execute("""
            SELECT id, name FROM vendors_providers
            WHERE category LIKE ? AND country = ? AND is_active = TRUE
            ORDER BY sort_order, name
        """, (cat_pattern, country)).fetchall()
    else:
        rows = conn.execute("""
            SELECT id, name FROM vendors_providers
            WHERE category LIKE ? AND is_active = TRUE
            ORDER BY sort_order, name
        """, (cat_pattern,)).fetchall()
    conn.close()
    return [dict(r) for r in rows]


@app.route('/api/vendors-for-service')
@login_required
def api_vendors_for_service():
    """AJAX endpoint: return vendors for a given service_name, optionally filtered by country."""
    service_name = request.args.get('service_name', '').strip()
    country = request.args.get('country', '').strip() or None
    if not service_name:
        return jsonify([])
    vendors = get_vendors_for_service(service_name, country)
    # Fallback: if no service-specific vendors found, return all Training Programs vendors
    if not vendors:
        logging.info(f"No vendors found for service '{service_name}' country '{country}', falling back to category")
        vendors = get_vendors_by_category('Training Programs', country)
    return jsonify(vendors)


