# ── PLAB Client Document Upload/Delete/Verify ──
PLAB_DOC_TYPES = {
    'personal': [
        'Photograph', 'Passport size Photograph',
        'Passport Copy (Front)', 'Passport Copy (Back)',
        'Aadhar Copy (Optional)'
    ],
    'academic': [
        'MBBS Final Certificate', 'MBBS Course Completion Certificate',
        'Internship Certificate', 'State Registration Certificate'
    ]
}

PLAB_ALL_REQUIRED_DOCS = PLAB_DOC_TYPES.get('personal', []) + PLAB_DOC_TYPES.get('academic', [])


@app.route('/operations/documents')
@admin_required
def ops_documents_list():
    """Documents overview — all clients with document upload status."""
    conn = get_db()
    search = request.args.get('search', '').strip()
    status_filter = request.args.get('status', '')
    page = max(1, int(request.args.get('page', 1)))
    per_page = 50
    try:
        q = """SELECT c.id, c.registration_number, c.first_name, c.last_name, c.prefix,
                      c.account_status, c.current_stage, c.created_at,
                      COUNT(d.id) as doc_count,
                      SUM(CASE WHEN d.status = 'verified' THEN 1 ELSE 0 END) as verified_count
               FROM plab_clients c
               LEFT JOIN plab_client_documents d ON d.client_id = c.id"""
        params = []
        wheres = []
        if search:
            wheres.append("(c.first_name ILIKE ? OR c.last_name ILIKE ? OR c.registration_number ILIKE ?)")
            params += [f'%{search}%', f'%{search}%', f'%{search}%']
        if wheres:
            q += " WHERE " + " AND ".join(wheres)
        q += " GROUP BY c.id, c.registration_number, c.first_name, c.last_name, c.prefix, c.account_status, c.current_stage, c.created_at"
        q += " ORDER BY c.id DESC"
        rows = conn.execute(q, params).fetchall()
        total_required = len(PLAB_ALL_REQUIRED_DOCS)
        all_clients = []
        for r in rows:
            rd = dict(r)
            rd['total_required'] = total_required
            rd['name'] = f"{r['prefix'] or ''} {r['first_name'] or ''} {r['last_name'] or ''}".strip()
            if status_filter == 'complete' and rd['doc_count'] < total_required:
                continue
            if status_filter == 'incomplete' and rd['doc_count'] >= total_required:
                continue
            if status_filter == 'none' and rd['doc_count'] > 0:
                continue
            all_clients.append(rd)
        # Stats before pagination
        total_filtered = len(all_clients)
        complete_count = sum(1 for c in all_clients if c.get('doc_count', 0) >= total_required)
        total_documents = sum(c.get('doc_count', 0) for c in all_clients)
        # Pagination
        total_pages = max(1, (total_filtered + per_page - 1) // per_page)
        page = min(page, total_pages)
        start = (page - 1) * per_page
        clients = all_clients[start:start + per_page]
    except Exception as e:
        logging.error(f"ops_documents_list error: {e}")
        clients = []
        total_filtered = complete_count = total_documents = 0
        total_pages = 1
    conn.close()
    return render_template('ops_documents_list.html',
                           clients=clients, search=search, status_filter=status_filter,
                           total_clients=total_filtered, complete_count=complete_count,
                           total_documents=total_documents,
                           total_required=len(PLAB_ALL_REQUIRED_DOCS),
                           plab_doc_types=PLAB_DOC_TYPES,
                           page=page, total_pages=total_pages, per_page=per_page,
                           start_index=start if clients else 0,
                           active_ops_page='documents')


@app.route('/operations/plab/<int:client_id>/upload-doc', methods=['POST'])
@admin_required
def ops_plab_upload_doc(client_id):
    """Upload document for a PLAB client."""
    conn = get_db()
    client = conn.execute("SELECT id FROM plab_clients WHERE id = ?", (client_id,)).fetchone()
    if not client:
        conn.close()
        return jsonify({'error': 'Client not found'}), 404
    doc_type = request.form.get('doc_type', 'Other')
    doc_category = request.form.get('doc_category', 'personal')
    file = request.files.get('file')
    if not file or not file.filename:
        conn.close()
        return jsonify({'error': 'No file selected'}), 400
    import os, uuid
    ext = file.filename.rsplit('.', 1)[-1].lower() if '.' in file.filename else 'pdf'
    # Detect content type from extension
    ct_map = {'pdf': 'application/pdf', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'png': 'image/png', 'gif': 'image/gif', 'webp': 'image/webp', 'doc': 'application/msword', 'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}
    content_type = ct_map.get(ext, 'application/octet-stream')
    # Read file binary for DB storage
    file_bytes = file.read()
    file_size = len(file_bytes)
    fname = f"plab_{client_id}_{uuid.uuid4().hex[:8]}.{ext}"
    conn.execute(
        "INSERT INTO plab_client_documents (client_id, doc_type, doc_category, file_name, file_path, file_size, uploaded_by, file_data, content_type) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (client_id, doc_type, doc_category, file.filename, f'db://{fname}', file_size, 'ops_team', file_bytes, content_type)
    )
    conn.commit()
    doc_id = conn.execute("SELECT id FROM plab_client_documents WHERE file_path = ?", (f'db://{fname}',)).fetchone()['id']
    conn.close()
    return jsonify({'success': True, 'doc_id': doc_id, 'file_name': file.filename, 'doc_type': doc_type})


@app.route('/api/plab-search')
@admin_required
def api_plab_search():
    """Search PLAB clients by name or registration number (autocomplete)."""
    q = request.args.get('q', '').strip()
    if len(q) < 2:
        return jsonify([])
    conn = get_db()
    rows = conn.execute(
        """SELECT id, registration_number, prefix, first_name, last_name
           FROM plab_clients
           WHERE first_name ILIKE ? OR last_name ILIKE ? OR registration_number ILIKE ?
           ORDER BY first_name, last_name LIMIT 15""",
        (f'%{q}%', f'%{q}%', f'%{q}%')
    ).fetchall()
    conn.close()
    results = []
    for r in rows:
        name = f"{r['prefix'] or ''} {r['first_name'] or ''} {r['last_name'] or ''}".strip()
        results.append({'id': r['id'], 'name': name, 'reg': r['registration_number']})
    return jsonify(results)


@app.route('/api/plab-client-docs/<int:client_id>')
@admin_required
def api_plab_client_docs(client_id):
    """Return documents for a client as JSON (used by drawer UI)."""
    conn = get_db()
    try:
        client = conn.execute("SELECT id, registration_number, prefix, first_name, last_name, account_status, current_stage FROM plab_clients WHERE id = ?", (client_id,)).fetchone()
        if not client:
            conn.close()
            return jsonify({'error': 'Client not found'}), 404
        rows = conn.execute("SELECT id, doc_type, doc_category, file_name, file_path, file_size, status, uploaded_by, uploaded_at::text as uploaded_at, notes FROM plab_client_documents WHERE client_id = ? ORDER BY doc_category, doc_type", (client_id,)).fetchall()
        docs = [dict(r) for r in rows]
        client_dict = dict(client)
        client_dict['name'] = f"{client['prefix'] or ''} {client['first_name'] or ''} {client['last_name'] or ''}".strip()
        all_required = PLAB_ALL_REQUIRED_DOCS
        uploaded_types = [d['doc_type'] for d in docs]
        missing = [dt for dt in all_required if dt not in uploaded_types]
    except Exception as e:
        conn.close()
        return jsonify({'error': str(e)}), 500
    conn.close()
    return jsonify({'client_id': client_id, 'client': client_dict, 'count': len(docs), 'docs': docs, 'missing': missing, 'total_required': len(all_required)})


@app.route('/operations/plab/doc/<int:doc_id>/file')
@admin_required
def ops_plab_serve_doc(doc_id):
    """Serve a PLAB client document file from DB (BYTEA)."""
    conn = get_db()
    doc = conn.execute("SELECT file_name, file_data, content_type FROM plab_client_documents WHERE id = ?", (doc_id,)).fetchone()
    conn.close()
    if not doc or not doc['file_data']:
        return "Document not found", 404
    file_data = doc['file_data']
    if isinstance(file_data, memoryview):
        file_data = bytes(file_data)
    ct = doc['content_type'] or 'application/octet-stream'
    return send_file(BytesIO(file_data), download_name=doc['file_name'], as_attachment=False, mimetype=ct)


