        sql = '''SELECT t.*, p.first_name, p.last_name, p.prefix
                 FROM ops_test_bookings t
                 LEFT JOIN plab_clients p ON t.registration_number = p.registration_number
                 WHERE 1=1'''
        params = []
        if reg:
            sql += ' AND t.registration_number = ?'
