# ---- Lead stages admin -------------------------------------------------
@app.route('/sales/stages', methods=['GET', 'POST'])
@login_required
@sales_crm_required
def sales_stages():
    user = get_user()
    role = get_sales_role(user)
    if role != 'admin':
        flash('Admins only', 'error')
        return redirect(url_for('sales_crm_dashboard'))
    conn = get_db()
    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'add':
            name = (request.form.get('name') or '').strip()
            if name:
                so = int(request.form.get('sort_order') or 0)
                color = (request.form.get('color') or '#3b82f6').strip()
                is_won = 1 if request.form.get('is_won') else 0
                is_lost = 1 if request.form.get('is_lost') else 0
                conn.execute(
                    'INSERT INTO sales_lead_stages (name, sort_order, color, is_won, is_lost) VALUES (?, ?, ?, ?, ?)',
                    (name, so, color, is_won, is_lost)
                )
                conn.commit()
                flash('Stage added', 'success')
        elif action == 'edit':
            sid = int(request.form.get('id'))
            conn.execute(
                'UPDATE sales_lead_stages SET name=?, sort_order=?, color=?, is_won=?, is_lost=?, is_active=? WHERE id=?',
                (
                    (request.form.get('name') or '').strip(),
                    int(request.form.get('sort_order') or 0),
                    (request.form.get('color') or '#3b82f6').strip(),
                    1 if request.form.get('is_won') else 0,
                    1 if request.form.get('is_lost') else 0,
                    1 if request.form.get('is_active') else 0,
                    sid
                )
            )
            conn.commit()
            flash('Stage updated', 'success')
        elif action == 'delete':
            sid = int(request.form.get('id'))
            conn.execute('UPDATE sales_lead_stages SET is_active = 0 WHERE id = ?', (sid,))
            conn.commit()
            flash('Stage deactivated', 'success')
        conn.close()
        return redirect(url_for('sales_stages'))

    stages = conn.execute(
        'SELECT * FROM sales_lead_stages ORDER BY is_active DESC, sort_order, name'
    ).fetchall()
    conn.close()
    return render_template('sales_stages.html', user=user, stages=stages,
                    active_section='sales')


# ---- Sales team admin --------------------------------------------------
@app.route('/sales/team', methods=['GET', 'POST'])
@login_required
@sales_crm_required
def sales_team_admin():
    user = get_user()
    role = get_sales_role(user)
    if role != 'admin':
        flash('Admins only', 'error')
        return redirect(url_for('sales_crm_dashboard'))
    conn = get_db()
    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'add':
            eid = int(request.form.get('employee_id'))
            r = (request.form.get('role') or 'rep').strip().lower()
            # Manager role is no longer offered in the UI; only accept rep/viewer from new adds.
            # ('manager' is still tolerated from legacy edit rows.)
            if r not in ('rep', 'manager', 'viewer'):
                r = 'rep'
            try:
                # No manager assignment — manager_employee_id is always NULL now.
                conn.execute(
                    'INSERT INTO sales_team (employee_id, manager_employee_id, role, is_active) VALUES (?, NULL, ?, 1) '
                    'ON CONFLICT (employee_id) DO UPDATE SET manager_employee_id = NULL, '
                    'role = EXCLUDED.role, is_active = 1',
                    (eid, r)
                )
                conn.commit()
                flash('Sales team member saved', 'success')
            except Exception as e:
                conn.rollback()
                flash(f'Could not save: {e}', 'error')
        elif action == 'update':
            eid = int(request.form.get('employee_id'))
            r = (request.form.get('role') or 'rep').strip().lower()
            if r not in ('rep', 'manager', 'viewer'):
                r = 'rep'
            try:
                # Role change only; manager hierarchy is no longer used.
                conn.execute(
                    'UPDATE sales_team SET role = ?, manager_employee_id = NULL WHERE employee_id = ?',
                    (r, eid)
                )
                conn.commit()
                flash('Member updated', 'success')
            except Exception as e:
                conn.rollback()
                flash(f'Could not update: {e}', 'error')
        elif action == 'remove':
            eid = int(request.form.get('employee_id'))
            conn.execute('UPDATE sales_team SET is_active = 0 WHERE employee_id = ?', (eid,))
            conn.commit()
            flash('Removed from sales team', 'success')
        conn.close()
        return redirect(url_for('sales_team_admin'))

    members = conn.execute('''
        SELECT st.employee_id, st.role, st.manager_employee_id, st.is_active,
               e.name, e.emp_code, e.photo_url, e.designation, e.reporting_to,
               m.name AS manager_name
        FROM sales_team st
        JOIN employees e ON st.employee_id = e.id
        LEFT JOIN employees m ON st.manager_employee_id = m.id
        WHERE st.is_active = 1
        ORDER BY st.role DESC, e.name
    ''').fetchall()
    member_ids = [m['employee_id'] for m in members]
    # Only show employees who already have Sales module access — they need it to use the CRM.
    # Admins are always allowed (is_admin = 1 bypasses the module_access check at runtime).
    available_emps_q = (
        "SELECT e.id, e.name, e.emp_code, e.designation, e.reporting_to FROM employees e "
        "WHERE e.is_active = 1 AND e.emp_code != 'admin' "
        "AND (e.is_admin = 1 OR EXISTS ("
        "  SELECT 1 FROM module_access ma "
        "  WHERE ma.employee_id = e.id AND ma.module = 'sales' AND ma.is_active = 1"
        "))"
    )
    if member_ids:
        ph = ','.join(['?'] * len(member_ids))
        available_emps_q += f' AND e.id NOT IN ({ph})'
        available_emps = conn.execute(available_emps_q + ' ORDER BY e.name', member_ids).fetchall()
    else:
        available_emps = conn.execute(available_emps_q + ' ORDER BY e.name').fetchall()
    # Count employees who have sales module access but aren't yet on the team — surfaced as a hint.
    no_access_count = conn.execute(
        "SELECT COUNT(*) AS c FROM employees e "
        "WHERE e.is_active = 1 AND e.emp_code != 'admin' AND e.is_admin = 0 "
        "AND NOT EXISTS (SELECT 1 FROM module_access ma "
        "                WHERE ma.employee_id = e.id AND ma.module = 'sales' AND ma.is_active = 1)"
    ).fetchone()
    no_access_count = no_access_count['c'] if no_access_count else 0
    conn.close()
    return render_template('sales_team.html', user=user, members=members,
                           available_emps=available_emps,
                           no_access_count=no_access_count,
                    active_section='sales')


# ---- Leads -------------------------------------------------------------
@app.route('/sales/leads')
@login_required
@sales_crm_required
def sales_leads_list():
    user = get_user()
    role = get_sales_role(user)
    visible_ids = get_visible_sales_employee_ids(user)
    if not visible_ids:
        return render_template('sales_leads.html', user=user, leads=[], stages=[], owners=[], role=role,
                    active_section='sales')
    placeholders = ','.join(['?'] * len(visible_ids))
    f_stage = request.args.get('stage')
    f_owner = request.args.get('owner')
    f_hot = request.args.get('hot')

    where = [f'sl.owner_employee_id IN ({placeholders})']
    params = list(visible_ids)
    if f_stage and f_stage.isdigit():
        where.append('sl.stage_id = ?'); params.append(int(f_stage))
    if f_owner and f_owner.isdigit():
        where.append('sl.owner_employee_id = ?'); params.append(int(f_owner))
    if f_hot == '1':
        where.append('sl.is_hot = 1')

    conn = get_db()
    leads = conn.execute(
        f'''SELECT sl.*, s.name AS stage_name, s.color AS stage_color,
                  s.is_won AS stage_won, s.is_lost AS stage_lost,
                  e.name AS owner_name, e.photo_url AS owner_photo,
                  ps.name AS product_name, p.name AS project_name
           FROM sales_leads sl
           LEFT JOIN sales_lead_stages s ON sl.stage_id = s.id
           LEFT JOIN employees e ON sl.owner_employee_id = e.id
           LEFT JOIN products_services ps ON sl.product_id = ps.id
           LEFT JOIN projects p ON ps.project_id = p.id
           WHERE {' AND '.join(where)}
           ORDER BY sl.is_hot DESC, sl.expected_close_date NULLS LAST, sl.created_at DESC''',
        params
    ).fetchall()
    stages = conn.execute('SELECT * FROM sales_lead_stages WHERE is_active = 1 ORDER BY sort_order').fetchall()
    owners = conn.execute(
        f'SELECT id, name, photo_url FROM employees WHERE id IN ({placeholders}) ORDER BY name',
        visible_ids
    ).fetchall()
    conn.close()
    leads_dicts = []
    for l in leads:
        d = dict(l)
        d['photo_src'] = d.get('owner_photo') or '/static/default-avatar.png'
        leads_dicts.append(d)
    return render_template('sales_leads.html', user=user, leads=leads_dicts,
                           stages=stages, owners=owners, role=role,
                           f_stage=f_stage, f_owner=f_owner, f_hot=f_hot,
                    active_section='sales')


@app.route('/sales/leads/add', methods=['GET', 'POST'])
@login_required
@sales_write_required
def sales_leads_add():
    user = get_user()
    role = get_sales_role(user)
    visible_ids = get_visible_sales_employee_ids(user)
    conn = get_db()
    if request.method == 'POST':
        # Non-admin users always own their own leads; only admin can assign to others
        if role == 'admin':
            owner = request.form.get('owner_employee_id')
            owner_id = int(owner) if owner and owner.isdigit() else user['id']
        else:
            owner_id = user['id']
        product_id = request.form.get('product_id')
        product_id = int(product_id) if product_id and product_id.isdigit() else None
        stream_id = request.form.get('stream_id')
        stream_id = int(stream_id) if stream_id and stream_id.isdigit() else None
        stage_id = request.form.get('stage_id')
        stage_id = int(stage_id) if stage_id and stage_id.isdigit() else None
        try:
            ev = float(request.form.get('expected_value') or 0)
        except ValueError:
            ev = 0.0
        ecd = request.form.get('expected_close_date') or None
        lead_name_new = (request.form.get('lead_name') or '').strip() or 'Untitled lead'
        company_new = (request.form.get('company') or '').strip()
        conn.execute(
            '''INSERT INTO sales_leads
               (lead_name, company, phone, email, source, product_id, stream_id, stage_id,
                owner_employee_id, expected_value, expected_close_date, is_hot, notes, created_by)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
            (
                lead_name_new, company_new,
                (request.form.get('phone') or '').strip(),
                (request.form.get('email') or '').strip(),
                (request.form.get('source') or '').strip(),
                product_id, stream_id, stage_id, owner_id, ev, ecd,
                1 if request.form.get('is_hot') else 0,
                (request.form.get('notes') or '').strip(),
                user['id']
            )
        )
        # If stage is Won, auto-create closure for the newly added lead
        if stage_id:
            won_stage = conn.execute(
                'SELECT id FROM sales_lead_stages WHERE id = ? AND is_won = 1',
                (stage_id,)
            ).fetchone()
            if won_stage:
                new_lead_row = conn.execute(
                    'SELECT id FROM sales_leads WHERE lead_name = ? AND owner_employee_id = ? ORDER BY id DESC LIMIT 1',
                    (lead_name_new, owner_id)
                ).fetchone()
                new_lead_id = new_lead_row['id'] if new_lead_row else None
                if new_lead_id:
                    try:
                        cl_revenue = float(request.form.get('closure_revenue') or ev or 0)
                    except ValueError:
                        cl_revenue = ev or 0.0
                    try:
                        cl_cost = float(request.form.get('closure_cost') or 0)
                    except ValueError:
                        cl_cost = 0.0
                    cl_margin = cl_revenue - cl_cost
                    cl_currency = (request.form.get('closure_currency') or 'INR').upper()
                    cl_close_date = datetime.now().strftime('%Y-%m-%d')
                    cl_product_name = ''
                    cl_project_id = None
                    if product_id:
                        prow = conn.execute(
                            'SELECT name, project_id FROM products_services WHERE id = ?',
                            (product_id,)
                        ).fetchone()
                        if prow:
                            cl_product_name = prow['name']
                            cl_project_id = prow['project_id']
                    conn.execute(
                        '''INSERT INTO sales_closures
                           (lead_id, employee_id, product_id, product_name, project_id,
                            client_name, revenue, cost, margin, currency, close_date,
                            notes, created_by)
                           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
                        (
                            new_lead_id, owner_id, product_id, cl_product_name or None,
                            cl_project_id,
                            company_new or lead_name_new,
                            cl_revenue, cl_cost, cl_margin, cl_currency, cl_close_date,
                            f'Auto-closure: {lead_name_new}',
                            user['id']
                        )
                    )
                    flash('Closure auto-recorded from won lead', 'success')
        conn.commit()
        conn.close()
        flash('Lead added', 'success')
        return redirect(url_for('sales_leads_list'))

    stages = conn.execute('SELECT * FROM sales_lead_stages WHERE is_active = 1 ORDER BY sort_order').fetchall()
    won_stage_ids = [s['id'] for s in stages if s['is_won']]
    products = conn.execute(
        "SELECT id, name FROM products_services WHERE status = 'active' ORDER BY name"
    ).fetchall()
    streams = conn.execute("SELECT id, name FROM revenue_streams WHERE is_active = 1 ORDER BY name").fetchall()
    if visible_ids:
        ph = ','.join(['?'] * len(visible_ids))
        owners = conn.execute(
            f'SELECT id, name FROM employees WHERE id IN ({ph}) ORDER BY name',
            visible_ids
        ).fetchall()
    else:
        owners = []
    conn.close()
    return render_template('sales_lead_form.html', user=user, lead=None, mode='add',
                           stages=stages, products=products, streams=streams, owners=owners,
                           role=role, won_stage_ids=won_stage_ids,
                           already_has_closure=False,
                    active_section='sales')


@app.route('/sales/leads/<int:lead_id>/edit', methods=['GET', 'POST'])
@login_required
@sales_write_required
def sales_leads_edit(lead_id):
    user = get_user()
    role = get_sales_role(user)
    visible_ids = get_visible_sales_employee_ids(user)
    conn = get_db()
    lead = conn.execute('SELECT * FROM sales_leads WHERE id = ?', (lead_id,)).fetchone()
    if not lead:
        conn.close()
        flash('Lead not found', 'error')
        return redirect(url_for('sales_leads_list'))
    if lead['owner_employee_id'] not in visible_ids and role != 'admin':
        conn.close()
        flash('Access denied', 'error')
        return redirect(url_for('sales_leads_list'))
    if request.method == 'POST':
        # Non-admin users keep the existing owner; only admin can reassign
        if role == 'admin':
            owner = request.form.get('owner_employee_id')
            owner_id = int(owner) if owner and owner.isdigit() else lead['owner_employee_id']
        else:
            owner_id = lead['owner_employee_id']
        product_id = request.form.get('product_id')
        product_id = int(product_id) if product_id and product_id.isdigit() else None
        stream_id = request.form.get('stream_id')
        stream_id = int(stream_id) if stream_id and stream_id.isdigit() else None
        stage_id = request.form.get('stage_id')
        stage_id = int(stage_id) if stage_id and stage_id.isdigit() else None
        try:
            ev = float(request.form.get('expected_value') or 0)
        except ValueError:
            ev = 0.0
        ecd = request.form.get('expected_close_date') or None
        lead_name_new = (request.form.get('lead_name') or '').strip() or lead['lead_name']
        company_new = (request.form.get('company') or '').strip()
        conn.execute(
            '''UPDATE sales_leads SET
               lead_name = ?, company = ?, phone = ?, email = ?, source = ?,
               product_id = ?, stream_id = ?, stage_id = ?, owner_employee_id = ?,
               expected_value = ?, expected_close_date = ?, is_hot = ?, notes = ?,
               updated_at = CURRENT_TIMESTAMP
               WHERE id = ?''',
            (
                lead_name_new, company_new,
                (request.form.get('phone') or '').strip(),
                (request.form.get('email') or '').strip(),
                (request.form.get('source') or '').strip(),
                product_id, stream_id, stage_id, owner_id, ev, ecd,
                1 if request.form.get('is_hot') else 0,
                (request.form.get('notes') or '').strip(),
                lead_id
            )
        )
        # --- Auto-create closure when stage changes to Won -----------------
        if stage_id:
            won_stage = conn.execute(
                'SELECT id FROM sales_lead_stages WHERE id = ? AND is_won = 1',
                (stage_id,)
            ).fetchone()
            old_was_won = False
            if lead['stage_id']:
                old_won_check = conn.execute(
                    'SELECT id FROM sales_lead_stages WHERE id = ? AND is_won = 1',
                    (lead['stage_id'],)
                ).fetchone()
                old_was_won = old_won_check is not None
            if won_stage and not old_was_won:
                # Only auto-create if no closure already linked to this lead
                existing_closure = conn.execute(
                    'SELECT id FROM sales_closures WHERE lead_id = ?', (lead_id,)
                ).fetchone()
                if not existing_closure:
                    # Pull revenue/cost from form (shown when Won selected),
                    # fallback to expected_value for revenue
                    try:
                        cl_revenue = float(request.form.get('closure_revenue') or ev or 0)
                    except ValueError:
                        cl_revenue = ev or 0.0
                    try:
                        cl_cost = float(request.form.get('closure_cost') or 0)
                    except ValueError:
                        cl_cost = 0.0
                    cl_margin = cl_revenue - cl_cost
                    cl_currency = (request.form.get('closure_currency') or 'INR').upper()
                    cl_close_date = datetime.now().strftime('%Y-%m-%d')
                    # Resolve product name and project
                    cl_product_name = ''
                    cl_project_id = None
                    if product_id:
                        prow = conn.execute(
                            'SELECT name, project_id FROM products_services WHERE id = ?',
                            (product_id,)
                        ).fetchone()
                        if prow:
                            cl_product_name = prow['name']
                            cl_project_id = prow['project_id']
                    conn.execute(
                        '''INSERT INTO sales_closures
                           (lead_id, employee_id, product_id, product_name, project_id,
                            client_name, revenue, cost, margin, currency, close_date,
                            notes, created_by)
                           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
                        (
                            lead_id, owner_id, product_id, cl_product_name or None,
                            cl_project_id,
                            company_new or lead_name_new,
                            cl_revenue, cl_cost, cl_margin, cl_currency, cl_close_date,
                            f'Auto-closure: {lead_name_new}',
                            user['id']
                        )
                    )
                    flash('Closure auto-recorded from won lead', 'success')
        # -------------------------------------------------------------------
        conn.commit()
        conn.close()
        flash('Lead updated', 'success')
        return redirect(url_for('sales_leads_list'))

    stages = conn.execute('SELECT * FROM sales_lead_stages WHERE is_active = 1 ORDER BY sort_order').fetchall()
    won_stage_ids = [s['id'] for s in stages if s['is_won']]
    already_has_closure = False
    if lead:
        already_has_closure = conn.execute(
            'SELECT id FROM sales_closures WHERE lead_id = ?', (lead_id,)
        ).fetchone() is not None
    products = conn.execute(
        "SELECT id, name FROM products_services WHERE status = 'active' ORDER BY name"
    ).fetchall()
    streams = conn.execute("SELECT id, name FROM revenue_streams WHERE is_active = 1 ORDER BY name").fetchall()
    if visible_ids:
        ph = ','.join(['?'] * len(visible_ids))
        owners = conn.execute(
            f'SELECT id, name FROM employees WHERE id IN ({ph}) ORDER BY name',
            visible_ids
        ).fetchall()
    else:
        owners = []
    conn.close()
    return render_template('sales_lead_form.html', user=user, lead=lead, mode='edit',
                           stages=stages, products=products, streams=streams, owners=owners,
                           role=role, won_stage_ids=won_stage_ids,
                           already_has_closure=already_has_closure,
                    active_section='sales')


