@app.route('/partner/register/send-otp', methods=['POST'])
def partner_send_otp():
    """Send OTP to partner email."""
    try:
        data = request.get_json()
        token = data.get('token', '').strip()

        if not token:
            return jsonify({'error': 'Token required'}), 400

        conn = get_db()
        invitation = conn.execute('''
            SELECT id, email, status FROM partner_invitations WHERE token = ?
        ''', (token,)).fetchone()

        if not invitation or invitation['status'] != 'pending':
            conn.close()
            return jsonify({'error': 'Invalid or expired token'}), 400

        email = invitation['email']

        # Generate 6-digit OTP
        otp_code = str(random.randint(100000, 999999))
        expires_at = datetime.now() + timedelta(minutes=10)

        # Store OTP
        conn.execute('''
            INSERT INTO partner_otps (email, otp_code, token, expires_at, verified)
            VALUES (?, ?, ?, ?, FALSE)
        ''', (email, otp_code, token, expires_at))
        conn.commit()

        # Send OTP email
        from email_utils import send_email
        send_email(
            [email],
            'Your GooCampus Partner Portal OTP',
            f'''
            <html>
                <body style="font-family: Arial, sans-serif; color: #333; line-height: 1.6; margin: 0; padding: 0;">
                    <div style="background-color: #1e3a5f; padding: 20px; text-align: center;">
                        <h1 style="color: white; margin: 0; font-size: 24px;">GooCampus Partner Portal</h1>
                    </div>
                    <div style="padding: 30px; background-color: white;">
                        <h2 style="color: #1e3a5f; margin-top: 0;">Email Verification</h2>
                        <p>Your one-time verification code is:</p>
                        <div style="text-align: center; margin: 25px 0;">
                            <span style="background: #f0f4f8; padding: 16px 32px; font-size: 32px; font-weight: bold; letter-spacing: 8px; color: #1e3a5f; border-radius: 8px; display: inline-block;">{otp_code}</span>
                        </div>
                        <p style="color: #666; font-size: 14px;">This code will expire in 10 minutes. Do not share it with anyone.</p>
                        <p style="margin-top: 30px;">Best regards,<br><strong style="color: #1e3a5f;">GooCampus Team</strong></p>
                    </div>
                    <div style="background-color: #f5f5f5; padding: 15px; text-align: center; border-top: 3px solid #F58220;">
                        <p style="color: #999; font-size: 11px; margin: 0;">GooCampus Edu Solutions Pvt Ltd</p>
                    </div>
                </body>
            </html>
            '''
        )

        conn.close()
        return jsonify({'success': True, 'message': 'OTP sent successfully'}), 200
    except Exception as e:
        logging.error(f"partner_send_otp: {e}")
        return jsonify({'error': str(e)}), 500


@app.route('/partner/register/verify-otp', methods=['POST'])
def partner_verify_otp():
    """Verify OTP and set session for partner registration."""
    try:
        data = request.get_json()
        otp = data.get('otp_code', data.get('otp', '')).strip()
        token = data.get('token', '').strip()

        if not otp or not token:
            return jsonify({'error': 'OTP and token required'}), 400

        # Look up email from invitation token
        conn = get_db()
        invitation = conn.execute('''
            SELECT email FROM partner_invitations WHERE token = ?
        ''', (token,)).fetchone()

        if not invitation:
            conn.close()
            return jsonify({'error': 'Invalid token'}), 400

        email = invitation['email']

        otp_record = conn.execute('''
            SELECT id, verified, expires_at FROM partner_otps
            WHERE email = ? AND token = ? AND otp_code = ?
        ''', (email, token, otp)).fetchone()

        if not otp_record:
            conn.close()
            return jsonify({'error': 'Invalid OTP'}), 400

        if otp_record['verified']:
            conn.close()
            return jsonify({'error': 'OTP already verified'}), 400

        # Check expiry — handle both string and datetime from PostgreSQL
        exp = otp_record['expires_at']
        if isinstance(exp, str):
            expires_at = datetime.fromisoformat(exp)
        else:
            expires_at = exp
        if datetime.now() > expires_at:
            conn.close()
            return jsonify({'error': 'OTP has expired'}), 400

        # Mark as verified
        conn.execute('''
            UPDATE partner_otps SET verified = TRUE WHERE email = ? AND token = ? AND otp_code = ?
        ''', (email, token, otp))
        conn.commit()
        conn.close()

        session['partner_register_token'] = token
        session['partner_register_email'] = email

        return jsonify({'success': True, 'message': 'OTP verified successfully', 'onboard_token': token}), 200
    except Exception as e:
        logging.error(f"partner_verify_otp: {e}")
        return jsonify({'error': str(e)}), 500


