def _emp_code_from_number(num_str):
    """Convert fingerprint device number (e.g. '1', '6', '11') to HR emp_code (GC001, GC006, GC011)."""
    try:
        n = int(float(str(num_str)))
        return f'GC{n:03d}'
    except (ValueError, TypeError):
        return ''


def _parse_time_minutes(time_str):
    """Convert 'HH:MM' or 'H:MM' to total minutes. Returns 0 for empty/invalid."""
    if not time_str or not time_str.strip():
        return 0
    try:
        parts = time_str.strip().split(':')
        return int(parts[0]) * 60 + int(parts[1])
    except (ValueError, IndexError):
        return 0


@app.route('/admin/upload-attendance', methods=['GET', 'POST'])
@admin_required
def upload_attendance():
    user = get_user()
    if request.method == 'POST':
        file = request.files.get('attendance_file')
        if not file or not file.filename:
            flash('Please select a file', 'error')
            return render_template('upload_attendance.html', user=user,
                    active_section='hr')

        if not file.filename.lower().endswith(('.xls', '.xlsx')):
            flash('Only .xls and .xlsx files are supported', 'error')
            return render_template('upload_attendance.html', user=user,
                    active_section='hr')

        import tempfile

        # Save uploaded file temporarily — preserve original extension
        file_ext = os.path.splitext(file.filename)[1].lower() or '.xlsx'
        tmp = tempfile.NamedTemporaryFile(delete=False, suffix=file_ext)
        file.save(tmp.name)
        tmp.close()
        tmp_path = tmp.name

        try:
            # ── Step 1: Open the workbook ──
            sheet = None
            use_openpyxl = False

            # Try xlrd first for .xls files
            try:
                import xlrd
                wb = xlrd.open_workbook(tmp_path)
                sheet = wb.sheets()[0]
                logging.info(f"Attendance file opened with xlrd ({sheet.nrows} rows)")
            except ImportError:
                logging.info("xlrd not available, using openpyxl")
            except Exception as xlrd_err:
                logging.info(f"xlrd failed ({xlrd_err}), trying openpyxl")

            # Fall back to openpyxl
            if sheet is None:
                from openpyxl import load_workbook as load_wb
                wb = load_wb(tmp_path, data_only=True)
                sheet = wb.active
                use_openpyxl = True
                logging.info(f"Attendance file opened with openpyxl ({sheet.max_row} rows)")

            # ── Step 2: Build employee lookup ──
            conn = get_db()
            employees = conn.execute("SELECT id, emp_code FROM employees WHERE is_active = 1").fetchall()
            code_map = {e['emp_code']: e['id'] for e in employees}
            logging.info(f"Employee lookup: {len(code_map)} active employees")

            # ── Step 3: Read all rows into memory ──
            def s(v):
                """Safe string conversion."""
                return str(v).strip() if v is not None else ''

            if use_openpyxl:
                all_rows = list(sheet.iter_rows(values_only=True))
            else:
                all_rows = []
                for r in range(sheet.nrows):
                    all_rows.append(tuple(sheet.cell(r, c).value for c in range(sheet.ncols)))

            logging.info(f"Loaded {len(all_rows)} rows into memory")

            # ── Step 4: Detect format and parse ──
            skipped = 0
            rows = []

            first_cell = s(all_rows[0][0]) if all_rows else ''
            is_flat = first_cell.lower() in ('date', 'attendance_date', 'attendance date')
            logging.info(f"File format: {'flat table' if is_flat else 'raw fingerprint'}")

            if is_flat:
                # Flat table: Date, Emp Code, Name, Shift, SchedIn, SchedOut,
                #             ActualIn, ActualOut, WorkDur, OT, TotalDur,
                #             LateBy, EarlyGoing, Status, PunchRecords
                for row in all_rows[1:]:
                    date_val = s(row[0])
                    emp_code = s(row[1])
                    if not date_val or not emp_code:
                        continue
                    if not emp_code.startswith('GC'):
                        emp_code = _emp_code_from_number(emp_code)
                    employee_id = code_map.get(emp_code)
                    if not employee_id:
                        skipped += 1
                        continue
                    parsed_date = date_val
                    for fmt in ('%Y-%m-%d', '%d-%b-%Y', '%d/%m/%Y', '%m/%d/%Y'):
                        try:
                            parsed_date = datetime.strptime(date_val, fmt).strftime('%Y-%m-%d')
                            break
                        except ValueError:
                            continue
                    rows.append((
                        employee_id, parsed_date,
                        s(row[3]), s(row[4]), s(row[5]),
                        s(row[6]), s(row[7]), s(row[8]),
                        s(row[9]), s(row[10]),
                        s(row[11]), s(row[12]), s(row[13]),
                        s(row[14]) if len(row) > 14 else ''
                    ))
            else:
                # Raw fingerprint: Attendance Date headers + SNo/E.Code rows
                current_date = None
                for row in all_rows:
                    ncols = len(row)
                    b = s(row[1]) if ncols > 1 else ''

                    if b == 'Attendance Date :':
                        current_date = s(row[5]) if ncols > 5 else ''
                        continue
                    if not current_date:
                        continue
                    try:
                        float(row[1])
                    except (ValueError, TypeError):
                        continue
                    e_code_raw = s(row[2]) if ncols > 2 else ''
                    if not e_code_raw:
                        continue
                    emp_code = _emp_code_from_number(e_code_raw)
                    employee_id = code_map.get(emp_code)
                    if not employee_id:
                        skipped += 1
                        continue
                    try:
                        parsed_date = datetime.strptime(current_date, '%d-%b-%Y').strftime('%Y-%m-%d')
                    except ValueError:
                        parsed_date = current_date
                    rows.append((
                        employee_id, parsed_date,
                        s(row[5]) if ncols>5 else '', s(row[6]) if ncols>6 else '', s(row[7]) if ncols>7 else '',
                        s(row[9]) if ncols>9 else '', s(row[10]) if ncols>10 else '', s(row[11]) if ncols>11 else '',
                        s(row[12]) if ncols>12 else '', s(row[13]) if ncols>13 else '',
                        s(row[14]) if ncols>14 else '', s(row[15]) if ncols>15 else '', s(row[16]) if ncols>16 else '',
                        s(row[18]) if ncols>18 else ''
                    ))

            logging.info(f"Parsed {len(rows)} attendance rows, {skipped} skipped")

            # ── Step 5: Delete existing records for the date range, then bulk insert ──
            if rows:
                dates = set(r[1] for r in rows)
                min_date = min(dates)
                max_date = max(dates)
                emp_ids = set(r[0] for r in rows)

                # Delete old records in the date range for these employees
                for eid in emp_ids:
                    conn.execute(
                        "DELETE FROM attendance_logs WHERE employee_id = ? AND attendance_date >= ? AND attendance_date <= ?",
                        (eid, min_date, max_date)
                    )

                # Insert all rows fresh
                for row in rows:
                    conn.execute("""INSERT INTO attendance_logs (
                        employee_id, attendance_date, shift, scheduled_in, scheduled_out,
                        actual_in, actual_out, work_duration, overtime, total_duration,
                        late_by, early_going_by, status, punch_records
                    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", row)

                conn.commit()
                logging.info(f"Attendance import committed: {len(rows)} records")

            conn.close()
            flash(f'Import complete: {len(rows)} records imported for {len(set(r[0] for r in rows))} employees ({skipped} skipped — unmatched codes)', 'success')

        except Exception as e:
            import traceback
            logging.error(f"Attendance import error: {traceback.format_exc()}")
            flash(f'Import error: {str(e)}', 'error')
        finally:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass

        return redirect(url_for('upload_attendance'))

    return render_template('upload_attendance.html', user=user,
                    active_section='hr')


@app.route('/time-log')
@login_required
def time_log():
    user = get_user()
    conn = get_db()

    # Determine month/year
    now = datetime.now()
    try:
        month = int(request.args.get('month', now.month))
        year = int(request.args.get('year', now.year))
    except (ValueError, TypeError):
        month, year = now.month, now.year

    # Date range for selected month
    import calendar as cal_mod
    _, days_in_month = cal_mod.monthrange(year, month)
    date_from = f'{year}-{month:02d}-01'
    date_to = f'{year}-{month:02d}-{days_in_month:02d}'

    # Admin/management sees all or filtered; employee sees own
    f_employee = request.args.get('employee', '').strip()
    is_admin_view = user['is_admin'] == 1 or user['emp_code'] in MANAGEMENT_CODES

    if is_admin_view:
        if f_employee:
            query = """
                SELECT al.*, e.name AS employee_name, e.emp_code, e.department, e.photo_url
                FROM attendance_logs al
                JOIN employees e ON al.employee_id = e.id
                WHERE al.attendance_date >= ? AND al.attendance_date <= ?
                  AND (LOWER(e.name) = LOWER(?) OR LOWER(e.emp_code) = LOWER(?)
                       OR LOWER(e.name) LIKE LOWER(?) OR LOWER(e.emp_code) LIKE LOWER(?))
                ORDER BY al.attendance_date ASC
            """
            like = f'%{f_employee}%'
            logs = conn.execute(query, (date_from, date_to, f_employee, f_employee, like, like)).fetchall()
        else:
            query = """
                SELECT al.*, e.name AS employee_name, e.emp_code, e.department, e.photo_url
                FROM attendance_logs al
                JOIN employees e ON al.employee_id = e.id
                WHERE al.attendance_date >= ? AND al.attendance_date <= ?
                ORDER BY e.name ASC, al.attendance_date ASC
            """
            logs = conn.execute(query, (date_from, date_to)).fetchall()
    else:
        query = """
            SELECT al.*, e.name AS employee_name, e.emp_code, e.department, e.photo_url
            FROM attendance_logs al
            JOIN employees e ON al.employee_id = e.id
            WHERE al.employee_id = ? AND al.attendance_date >= ? AND al.attendance_date <= ?
            ORDER BY al.attendance_date ASC
        """
        logs = conn.execute(query, (user['id'], date_from, date_to)).fetchall()

    # ── Fetch holidays for this month ──
    holidays_rows = conn.execute(
        "SELECT holiday_date, name, holiday_type FROM holidays WHERE holiday_date >= ? AND holiday_date <= ? ORDER BY holiday_date",
        (date_from, date_to)
    ).fetchall()
    holidays_map = {row['holiday_date']: dict(row) for row in holidays_rows}

    # ── Fetch approved leaves for this month ──
    leaves_rows = conn.execute("""
        SELECT lr.employee_id, lr.leave_date, lr.leave_type, lr.day_portion, lr.status
        FROM leave_records lr
        WHERE lr.leave_date >= ? AND lr.leave_date <= ? AND lr.status = 'approved'
    """, (date_from, date_to)).fetchall()
    # Key: (employee_id, date_str) → leave info
    from collections import defaultdict
    leaves_map = {}
    for lv in leaves_rows:
        key = (lv['employee_id'], lv['leave_date'])
        leaves_map[key] = {
            'leave_type': lv['leave_type'],
            'day_portion': lv['day_portion'],
            'status': lv['status']
        }

    # ── Fetch approved WFH for this month ──
    wfh_rows = conn.execute("""
        SELECT employee_id, from_date, to_date
        FROM wfh_requests
        WHERE status = 'approved'
          AND from_date <= ? AND to_date >= ?
    """, (date_to, date_from)).fetchall()
    # Build set of (employee_id, date_str) for WFH days
    wfh_set = set()
    for wfh in wfh_rows:
        try:
            wfh_start = datetime.strptime(wfh['from_date'], '%Y-%m-%d')
            wfh_end = datetime.strptime(wfh['to_date'], '%Y-%m-%d')
            cur = wfh_start
            while cur <= wfh_end:
                ds = cur.strftime('%Y-%m-%d')
                if date_from <= ds <= date_to:
                    wfh_set.add((wfh['employee_id'], ds))
                cur += timedelta(days=1)
        except Exception:
            pass

    # ── Build attendance lookup by (employee_id, date) ──
    logs_list = [dict(r) for r in logs]
    att_lookup = {}
    emp_info = {}
    for log in logs_list:
        eid = log['employee_id']
        att_lookup[(eid, log['attendance_date'])] = log
        if eid not in emp_info:
            emp_info[eid] = {
                'name': log['employee_name'], 'emp_code': log['emp_code'],
                'department': log['department'], 'photo_url': log.get('photo_url', '')
            }

    # If non-admin with no attendance records, still show calendar for self
    if not is_admin_view and user['id'] not in emp_info:
        emp_info[user['id']] = {
            'name': user['name'], 'emp_code': user['emp_code'],
            'department': user.get('department', ''), 'photo_url': user.get('photo_url', '')
        }

    # ── Build full calendar for each employee ──
    DAY_NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']

    emp_summaries = {}
    for eid, info in emp_info.items():
        s = {
            'name': info['name'], 'emp_code': info['emp_code'],
            'department': info['department'], 'photo_url': info['photo_url'],
            'total_work_mins': 0,
            'present_days': 0, 'absent_days': 0, 'late_days': 0,
            'weekly_off_days': 0, 'half_days': 0, 'no_punch_days': 0,
            'leave_days': 0, 'wfh_days': 0, 'holiday_days': 0,
            'in_out_days': 0, 'no_in_days': 0, 'no_out_days': 0,
            'full_days_work_mins': 0,  # work mins only for days with both in & out
            'full_days_total_mins': 0,  # total duration mins only for days with both in & out
            'days': [], 'employee_id': eid
        }

        for d in range(1, days_in_month + 1):
            date_str = f'{year}-{month:02d}-{d:02d}'
            dt_obj = datetime(year, month, d)
            weekday = dt_obj.weekday()  # 0=Mon, 6=Sun
            day_name = DAY_NAMES[weekday]
            is_weekend = weekday >= 5  # Sat/Sun

            att = att_lookup.get((eid, date_str))
            leave_info = leaves_map.get((eid, date_str))
            is_wfh = (eid, date_str) in wfh_set
            holiday_info = holidays_map.get(date_str)

            # Determine the day_type for coloring
            if holiday_info:
                day_type = 'holiday'
                s['holiday_days'] += 1
            elif is_weekend:
                day_type = 'weekend'
                s['weekly_off_days'] += 1
            elif leave_info:
                lv_days = 0.5 if leave_info['day_portion'] in ('first_half', 'second_half') else 1.0
                day_type = 'half_leave' if lv_days == 0.5 else 'leave'
                s['leave_days'] += lv_days
            elif is_wfh:
                day_type = 'wfh'
                s['wfh_days'] += 1
            else:
                day_type = 'weekday'

            # Build day record
            if att:
                day_rec = dict(att)
            else:
                day_rec = {
                    'attendance_date': date_str, 'employee_id': eid,
                    'employee_name': info['name'], 'emp_code': info['emp_code'],
                    'department': info['department'], 'photo_url': info['photo_url'],
                    'shift': '', 'scheduled_in': '', 'scheduled_out': '',
                    'actual_in': '', 'actual_out': '', 'work_duration': '',
                    'overtime': '', 'total_duration': '', 'late_by': '',
                    'early_going_by': '', 'status': '', 'punch_records': ''
                }

            day_rec['day_type'] = day_type
            day_rec['day_name'] = day_name
            day_rec['is_weekend'] = is_weekend
            day_rec['holiday_name'] = holiday_info['name'] if holiday_info else ''
            day_rec['leave_type'] = leave_info['leave_type'].capitalize() if leave_info else ''
            day_rec['leave_portion'] = leave_info['day_portion'] if leave_info else ''
            day_rec['is_wfh'] = is_wfh

            s['days'].append(day_rec)

            # Update attendance-based counters (only for actual attendance records)
            if att:
                status = (att.get('status') or '').strip()
                has_in = bool(att.get('actual_in') and att['actual_in'].strip() and att['actual_in'].strip() != '—')
                has_out = bool(att.get('actual_out') and att['actual_out'].strip() and att['actual_out'].strip() != '—')

                # Track In/Out, No In, No Out (only for working days)
                if day_type not in ('weekend', 'holiday'):
                    if has_in and has_out:
                        s['in_out_days'] += 1
                    elif has_in and not has_out:
                        s['no_out_days'] += 1
                    elif not has_in and has_out:
                        s['no_in_days'] += 1

                    # Determine punch tag for display
                    if has_in and not has_out:
                        day_rec['punch_tag'] = 'no_out'
                    elif not has_in and has_out:
                        day_rec['punch_tag'] = 'no_in'
                    elif has_in and has_out:
                        day_rec['punch_tag'] = 'full'
                    else:
                        day_rec['punch_tag'] = 'none'

                    # Present-day logic: count as present if they have at least an in or out
                    if leave_info and leave_info['day_portion'] in ('first_half', 'second_half'):
                        # Half-day leave: count 0.5 present + 0.5 leave (leave already counted above)
                        s['half_days'] += 1
                        s['present_days'] += 0.5
                    elif has_in or has_out:
                        # They showed up (even if missing one punch)
                        s['present_days'] += 1
                    elif leave_info or is_wfh:
                        pass  # On leave/WFH, already counted
                    elif 'Absent' in status:
                        s['absent_days'] += 1
                    # No attendance record and no leave/WFH → will be blank row

                # ── Calculate Total Hours from actual in/out times ──
                FULL_DAY_MINS = 540   # 9 hours = standard working day
                HALF_DAY_MINS = 240   # 4 hours = half-day minimum

                # Compute total_in_out from actual punch times
                total_in_out = 0
                if has_in and has_out:
                    try:
                        t_in = datetime.strptime(att['actual_in'].strip(), '%H:%M')
                        t_out = datetime.strptime(att['actual_out'].strip(), '%H:%M')
                        total_in_out = int((t_out - t_in).total_seconds() / 60)
                        if total_in_out < 0:
                            total_in_out = 0
                    except Exception:
                        total_in_out = _parse_time_minutes(att.get('total_duration', ''))

                # Total working hours = pure in-to-out
                day_rec['total_duration'] = f"{total_in_out // 60}:{total_in_out % 60:02d}" if total_in_out > 0 else ''

                # WHD (Working Hour Deficit) against 9-hour standard
                # For half-day leave: standard is 4h instead of 9h
                is_half_day = (day_rec.get('day_type') == 'half_leave')
                whd_standard = HALF_DAY_MINS if is_half_day else FULL_DAY_MINS

                if total_in_out > 0 and has_in and has_out:
                    deficit = whd_standard - total_in_out
                    if deficit > 0:
                        # Deficit — show difference in red
                        day_rec['whd'] = f"-{deficit // 60}:{deficit % 60:02d}"
                        day_rec['whd_ok'] = False
                    else:
                        # Met or exceeded — green tick
                        day_rec['whd'] = '✓'
                        day_rec['whd_ok'] = True
                else:
                    day_rec['whd'] = ''
                    day_rec['whd_ok'] = None

                s['total_work_mins'] += total_in_out

                # Track mins only for days with both in & out (for avg calculations)
                if has_in and has_out:
                    s['full_days_work_mins'] += total_in_out
                    s['full_days_total_mins'] += total_in_out

                late_mins = _parse_time_minutes(att.get('late_by', ''))
                if late_mins > 0:
                    s['late_days'] += 1
            else:
                day_rec['punch_tag'] = 'none'

        emp_summaries[eid] = s

    # Format summaries
    summaries = []
    for eid, s in sorted(emp_summaries.items(), key=lambda x: x[1]['name']):
        s['total_work_hrs'] = f"{s['total_work_mins'] // 60}h {s['total_work_mins'] % 60}m"
        # Average based only on days with both In & Out
        s['avg_work_hrs'] = ''
        if s['in_out_days'] > 0:
            avg = s['full_days_work_mins'] / s['in_out_days']
            s['avg_work_hrs'] = f"{int(avg) // 60}h {int(avg) % 60}m"
        summaries.append(s)

    # For admin: employee list for filter (include all employees, not just those with attendance)
    all_employees = []
    if is_admin_view:
        all_employees = conn.execute(
            "SELECT DISTINCT e.id, e.name, e.emp_code FROM employees e WHERE e.is_active = 1 ORDER BY e.name"
        ).fetchall()

    # Query last bulk report send date for this month/year
    last_report_sent = None
    if is_admin_view:
        try:
            last_log = conn.execute(
                "SELECT sent_at, sent_count FROM report_send_log "
                "WHERE send_type = 'bulk' AND month = ? AND year = ? "
                "ORDER BY sent_at DESC LIMIT 1",
                (month, year)
            ).fetchone()
            if last_log and last_log['sent_at']:
                ts = last_log['sent_at']
                if hasattr(ts, 'strftime'):
                    last_report_sent = ts.strftime('%d %b %Y, %I:%M %p')
                else:
                    last_report_sent = str(ts)
        except Exception:
            pass  # table may not exist yet

    conn.close()

    # Month names for picker
    month_names = ['January', 'February', 'March', 'April', 'May', 'June',
                   'July', 'August', 'September', 'October', 'November', 'December']

    return render_template('time_log.html',
        user=user,
        summaries=summaries,
        is_admin_view=is_admin_view,
        all_employees=all_employees,
        month=month, year=year,
        month_name=month_names[month - 1],
        f_employee=f_employee,
        month_names=month_names,
        last_report_sent=last_report_sent,
                    active_section='hr')


def _build_and_send_attendance_report(employee_id, month, year):
    """Core logic: build and send an attendance report email for one employee.
    Returns True on success, False on failure."""
    from email_utils import send_email
    import calendar as cal_mod

    conn = get_db()

    emp = conn.execute(
        "SELECT id, name, emp_code, email, department, reporting_to FROM employees WHERE id = ?",
        (employee_id,)
    ).fetchone()
    if not emp or not emp['email']:
        conn.close()
        return False

    cc_list = []
    if emp['reporting_to']:
        mgr = conn.execute("SELECT name, email FROM employees WHERE id = ?", (emp['reporting_to'],)).fetchone()
        if mgr and mgr['email']:
            cc_list.append(mgr['email'])

    # Build date range
    _, days_in_month = cal_mod.monthrange(year, month)
    date_from = f'{year}-{month:02d}-01'
    date_to = f'{year}-{month:02d}-{days_in_month:02d}'
    month_names = ['January', 'February', 'March', 'April', 'May', 'June',
                   'July', 'August', 'September', 'October', 'November', 'December']
    month_name = month_names[month - 1]

    # Fetch attendance logs
    logs = conn.execute("""
        SELECT * FROM attendance_logs
        WHERE employee_id = ? AND attendance_date >= ? AND attendance_date <= ?
        ORDER BY attendance_date ASC
    """, (employee_id, date_from, date_to)).fetchall()
    att_lookup = {str(row['attendance_date']): dict(row) for row in logs}
    logging.info(f"[EMAIL DEBUG] emp={employee_id} month={month}/{year} logs={len(logs)} att_keys={list(att_lookup.keys())[:5]}")

    # Fetch holidays
    holidays_rows = conn.execute(
        "SELECT holiday_date, name FROM holidays WHERE holiday_date >= ? AND holiday_date <= ?",
        (date_from, date_to)
    ).fetchall()
    holidays_map = {str(row['holiday_date']): row['name'] for row in holidays_rows}

    # Fetch approved leaves
    leaves_rows = conn.execute("""
        SELECT leave_date, leave_type, day_portion FROM leave_records
        WHERE employee_id = ? AND leave_date >= ? AND leave_date <= ? AND status = 'approved'
    """, (employee_id, date_from, date_to)).fetchall()
    leaves_map = {str(row['leave_date']): dict(row) for row in leaves_rows}

    # Fetch approved WFH
    wfh_rows = conn.execute("""
        SELECT from_date, to_date FROM wfh_requests
        WHERE employee_id = ? AND status = 'approved' AND from_date <= ? AND to_date >= ?
    """, (employee_id, date_to, date_from)).fetchall()
    wfh_dates = set()
    for wfh in wfh_rows:
        try:
            fd = wfh['from_date']
            td = wfh['to_date']
            wfh_start = fd if hasattr(fd, 'year') else datetime.strptime(str(fd), '%Y-%m-%d')
            wfh_end = td if hasattr(td, 'year') else datetime.strptime(str(td), '%Y-%m-%d')
            cur = wfh_start if isinstance(wfh_start, datetime) else datetime(wfh_start.year, wfh_start.month, wfh_start.day)
            end = wfh_end if isinstance(wfh_end, datetime) else datetime(wfh_end.year, wfh_end.month, wfh_end.day)
            while cur <= end:
                ds = cur.strftime('%Y-%m-%d')
                if date_from <= ds <= date_to:
                    wfh_dates.add(ds)
                cur += timedelta(days=1)
        except Exception:
            pass

    conn.close()

    # Build daily rows and compute stats
    DAY_NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
    FULL_DAY_MINS_CFG = 540   # 9 hours standard for WHD
    HALF_DAY_MINS_CFG = 240   # 4 hours half-day minimum

    stats = {
        'present': 0, 'absent': 0, 'leave': 0, 'wfh': 0,
        'holiday': 0, 'weekend': 0,
        'in_out': 0, 'no_in': 0, 'no_out': 0,
        'total_work_mins': 0, 'full_days_work_mins': 0, 'full_days_total_mins': 0
    }
    rows_html = []

    for d in range(1, days_in_month + 1):
        date_str = f'{year}-{month:02d}-{d:02d}'
        dt_obj = datetime(year, month, d)
        weekday = dt_obj.weekday()
        day_name = DAY_NAMES[weekday]
        is_weekend = weekday >= 5

        att = att_lookup.get(date_str)
        leave = leaves_map.get(date_str)
        is_wfh = date_str in wfh_dates
        holiday_name = holidays_map.get(date_str)

        has_in = bool(att and att.get('actual_in') and att['actual_in'].strip() and att['actual_in'].strip() != '—')
        has_out = bool(att and att.get('actual_out') and att['actual_out'].strip() and att['actual_out'].strip() != '—')

        # Determine day type and status HTML (matching web page badge style)
        badge = lambda text, bg, color: f'<span style="display:inline-block;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:600;background:{bg};color:{color};">{text}</span>'

        if holiday_name:
            day_type = 'holiday'
            status_html = badge('Holiday', '#FDF2F8', '#9D174D') + f' <span style="font-size:11px;color:#9D174D;">{holiday_name}</span>'
            stats['holiday'] += 1
            row_bg = '#FDF2F8'
        elif is_weekend:
            day_type = 'weekend'
            status_html = badge('Weekend', '#F5F3FF', '#3730A3')
            stats['weekend'] += 1
            row_bg = '#F5F3FF'
        elif leave and leave['day_portion'] in ('first_half', 'second_half'):
            day_type = 'half_leave'
            portion_label = leave['day_portion'].replace('_', ' ').title()
            leave_type = leave['leave_type'].capitalize()
            # Show punch status + half-leave tag (same as web page)
            if has_in and has_out:
                stats['in_out'] += 1
                punch_badge = badge('Present', '#F0FDF4', '#065F46')
            elif has_in:
                stats['no_out'] += 1
                punch_badge = badge('No Out', '#FFF7ED', '#9A3412')
            elif has_out:
                stats['no_in'] += 1
                punch_badge = badge('No In', '#FFF7ED', '#B45309')
            else:
                punch_badge = ''
            status_html = f'{punch_badge} {badge(f"½ {leave_type}", "#EFF6FF", "#1E40AF")} <span style="font-size:11px;color:#1E40AF;">({portion_label})</span>'
            stats['present'] += 0.5
            stats['leave'] += 0.5
            row_bg = '#EFF6FF'
        elif leave:
            day_type = 'leave'
            status_html = badge('On Leave', '#EFF6FF', '#1E40AF') + f' <span style="font-size:11px;color:#1E40AF;">{leave["leave_type"].capitalize()}</span>'
            stats['leave'] += 1
            row_bg = '#EFF6FF'
        elif is_wfh:
            day_type = 'wfh'
            status_html = badge('WFH', '#ECFEFF', '#0E7490')
            stats['wfh'] += 1
            row_bg = '#ECFEFF'
        elif has_in or has_out:
            day_type = 'present'
            stats['present'] += 1
            if has_in and has_out:
                stats['in_out'] += 1
                status_html = badge('Present', '#F0FDF4', '#065F46')
            elif has_in and not has_out:
                stats['no_out'] += 1
                status_html = badge('Present', '#F0FDF4', '#065F46') + ' ' + badge('No Out', '#FFF7ED', '#9A3412')
            else:
                stats['no_in'] += 1
                status_html = badge('Present', '#F0FDF4', '#065F46') + ' ' + badge('No In', '#FFF7ED', '#B45309')
            row_bg = '#FFFFFF'
        elif att and 'Absent' in (att.get('status') or ''):
            day_type = 'absent'
            if is_wfh:
                status_html = badge('WFH', '#ECFEFF', '#0E7490')
            else:
                status_html = badge('Absent', '#FEF2F2', '#991B1B')
            stats['absent'] += 1
            row_bg = '#FEF2F2'
        else:
            day_type = 'blank'
            status_html = '—'
            row_bg = '#FFFFFF'

        # Total hours — computed from actual in/out times
        FULL_DAY_MINS = 540   # 9 hours standard
        HALF_DAY_MINS = 240   # 4 hours half-day minimum
        total_in_out = 0
        if has_in and has_out and att:
            try:
                t_in = datetime.strptime(att['actual_in'].strip(), '%H:%M')
                t_out = datetime.strptime(att['actual_out'].strip(), '%H:%M')
                total_in_out = int((t_out - t_in).total_seconds() / 60)
                if total_in_out < 0:
                    total_in_out = 0
            except Exception:
                total_in_out = _parse_time_minutes(att.get('total_duration', ''))

        is_half_day = (day_type == 'half_leave')
        whd_standard = HALF_DAY_MINS if is_half_day else FULL_DAY_MINS

        # WHD calculation
        if total_in_out > 0 and has_in and has_out:
            deficit = whd_standard - total_in_out
            if deficit > 0:
                whd_display = f"-{deficit // 60}:{deficit % 60:02d}"
                whd_color = '#DC2626'
            else:
                whd_display = '&#10003;'
                whd_color = '#16A34A'
        else:
            whd_display = '—'
            whd_color = '#6B7280'

        stats['total_work_mins'] += total_in_out
        if has_in and has_out:
            stats['full_days_work_mins'] += total_in_out
            stats['full_days_total_mins'] += total_in_out

        # Format values
        actual_in = (att.get('actual_in') or '—') if att else '—'
        actual_out = (att.get('actual_out') or '—') if att else '—'
        total_display = f"{total_in_out // 60}:{total_in_out % 60:02d}" if total_in_out > 0 else '—'

        # Day name styling
        day_name_style = 'color: #7C3AED; font-weight: 600;' if is_weekend else 'color: #6B7280;'

        rows_html.append(f'''
            <tr style="background: {row_bg};">
                <td style="padding: 8px 12px; border-bottom: 1px solid #E5E7EB; font-weight: 600; color: #1e3a5f; white-space: nowrap;">{d:02d} {month_name[:3]}</td>
                <td style="padding: 8px 12px; border-bottom: 1px solid #E5E7EB;"><span style="{day_name_style}">{day_name}</span></td>
                <td style="padding: 8px 12px; border-bottom: 1px solid #E5E7EB; font-size: 13px;">{status_html}</td>
                <td style="padding: 8px 12px; border-bottom: 1px solid #E5E7EB; color: #6B7280;">{actual_in}</td>
                <td style="padding: 8px 12px; border-bottom: 1px solid #E5E7EB; color: #6B7280;">{actual_out}</td>
                <td style="padding: 8px 12px; border-bottom: 1px solid #E5E7EB; font-weight: 600;">{total_display}</td>
                <td style="padding: 8px 12px; border-bottom: 1px solid #E5E7EB; color: {whd_color}; font-weight: 600;">{whd_display}</td>
            </tr>
        ''')

    # Format stats
    total_work = f"{stats['total_work_mins'] // 60}h {stats['total_work_mins'] % 60}m"
    avg_work = '—'
    if stats['in_out'] > 0:
        avg_m = stats['full_days_work_mins'] / stats['in_out']
        avg_work = f"{int(avg_m) // 60}h {int(avg_m) % 60}m"

    # Build HTML email
    html_body = f'''
    <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 750px; margin: 0 auto; color: #1e3a5f;">
        <div style="background: #1e3a5f; padding: 24px 30px; border-radius: 8px 8px 0 0;">
            <h1 style="color: white; margin: 0; font-size: 20px;">Attendance Report — {month_name} {year}</h1>
            <p style="color: #94A3B8; margin: 6px 0 0; font-size: 14px;">{emp['name']} ({emp['emp_code']}) · {emp['department'] or 'N/A'}</p>
        </div>

        <div style="background: white; padding: 24px 30px; border: 1px solid #E5E7EB; border-top: none;">
            <h3 style="color: #1e3a5f; margin: 0 0 16px; font-size: 15px;">Summary</h3>
            <table style="width: 100%; border-collapse: collapse; margin-bottom: 24px;">
                <tr>
                    <td style="padding: 10px 14px; background: #F9FAFB; border-radius: 6px; text-align: center; width: 25%;">
                        <div style="font-size: 22px; font-weight: 800; color: #059669;">{int(stats['present'])}</div>
                        <div style="font-size: 11px; color: #6B7280; text-transform: uppercase; font-weight: 600;">Present</div>
                    </td>
                    <td style="width: 8px;"></td>
                    <td style="padding: 10px 14px; background: #F9FAFB; border-radius: 6px; text-align: center; width: 25%;">
                        <div style="font-size: 22px; font-weight: 800; color: #DC2626;">{stats['absent']}</div>
                        <div style="font-size: 11px; color: #6B7280; text-transform: uppercase; font-weight: 600;">Absent</div>
                    </td>
                    <td style="width: 8px;"></td>
                    <td style="padding: 10px 14px; background: #F9FAFB; border-radius: 6px; text-align: center; width: 25%;">
                        <div style="font-size: 22px; font-weight: 800; color: #1E40AF;">{int(stats['leave'])}</div>
                        <div style="font-size: 11px; color: #6B7280; text-transform: uppercase; font-weight: 600;">Leave</div>
                    </td>
                    <td style="width: 8px;"></td>
                    <td style="padding: 10px 14px; background: #F9FAFB; border-radius: 6px; text-align: center; width: 25%;">
                        <div style="font-size: 22px; font-weight: 800; color: #0E7490;">{stats['wfh']}</div>
                        <div style="font-size: 11px; color: #6B7280; text-transform: uppercase; font-weight: 600;">WFH</div>
                    </td>
                </tr>
            </table>
            <table style="width: 100%; border-collapse: collapse; margin-bottom: 24px;">
                <tr>
                    <td style="padding: 10px 14px; background: #F9FAFB; border-radius: 6px; text-align: center;">
                        <div style="font-size: 18px; font-weight: 800; color: #1e3a5f;">{total_work}</div>
                        <div style="font-size: 11px; color: #6B7280; text-transform: uppercase; font-weight: 600;">Total Hours</div>
                    </td>
                    <td style="width: 8px;"></td>
                    <td style="padding: 10px 14px; background: #F9FAFB; border-radius: 6px; text-align: center;">
                        <div style="font-size: 18px; font-weight: 800; color: #1e3a5f;">{avg_work}</div>
                        <div style="font-size: 11px; color: #6B7280; text-transform: uppercase; font-weight: 600;">Avg Hours (In&Out)</div>
                    </td>
                </tr>
            </table>
            <table style="width: 100%; border-collapse: collapse; margin-bottom: 24px;">
                <tr>
                    <td style="padding: 8px 14px; background: #F0FDF4; border-radius: 6px; text-align: center;">
                        <span style="font-weight: 700; color: #059669;">{stats['in_out']}</span>
                        <span style="font-size: 12px; color: #6B7280;"> In & Out</span>
                    </td>
                    <td style="width: 8px;"></td>
                    <td style="padding: 8px 14px; background: #FFF7ED; border-radius: 6px; text-align: center;">
                        <span style="font-weight: 700; color: #B45309;">{stats['no_in']}</span>
                        <span style="font-size: 12px; color: #6B7280;"> No In</span>
                    </td>
                    <td style="width: 8px;"></td>
                    <td style="padding: 8px 14px; background: #FFF7ED; border-radius: 6px; text-align: center;">
                        <span style="font-weight: 700; color: #9A3412;">{stats['no_out']}</span>
                        <span style="font-size: 12px; color: #6B7280;"> No Out</span>
                    </td>
                    <td style="width: 8px;"></td>
                    <td style="padding: 8px 14px; background: #FDF2F8; border-radius: 6px; text-align: center;">
                        <span style="font-weight: 700; color: #9D174D;">{stats['holiday']}</span>
                        <span style="font-size: 12px; color: #6B7280;"> Holidays</span>
                    </td>
                </tr>
            </table>

            <h3 style="color: #1e3a5f; margin: 0 0 12px; font-size: 15px;">Daily Log</h3>
            <table style="width: 100%; border-collapse: collapse; font-size: 13px;">
                <thead>
                    <tr style="background: #F3F4F6;">
                        <th style="padding: 10px 12px; text-align: left; font-size: 11px; font-weight: 700; color: #6B7280; text-transform: uppercase; border-bottom: 2px solid #E5E7EB;">Date</th>
                        <th style="padding: 10px 12px; text-align: left; font-size: 11px; font-weight: 700; color: #6B7280; text-transform: uppercase; border-bottom: 2px solid #E5E7EB;">Day</th>
                        <th style="padding: 10px 12px; text-align: left; font-size: 11px; font-weight: 700; color: #6B7280; text-transform: uppercase; border-bottom: 2px solid #E5E7EB;">Status</th>
                        <th style="padding: 10px 12px; text-align: left; font-size: 11px; font-weight: 700; color: #6B7280; text-transform: uppercase; border-bottom: 2px solid #E5E7EB;">In</th>
                        <th style="padding: 10px 12px; text-align: left; font-size: 11px; font-weight: 700; color: #6B7280; text-transform: uppercase; border-bottom: 2px solid #E5E7EB;">Out</th>
                        <th style="padding: 10px 12px; text-align: left; font-size: 11px; font-weight: 700; color: #6B7280; text-transform: uppercase; border-bottom: 2px solid #E5E7EB;">Total Hrs</th>
                        <th style="padding: 10px 12px; text-align: left; font-size: 11px; font-weight: 700; color: #6B7280; text-transform: uppercase; border-bottom: 2px solid #E5E7EB;">WHD - 9 HR</th>
                    </tr>
                </thead>
                <tbody>
                    {''.join(rows_html)}
                </tbody>
            </table>
        </div>

        <div style="background: #F9FAFB; padding: 16px 30px; border: 1px solid #E5E7EB; border-top: none; border-radius: 0 0 8px 8px; text-align: center;">
            <p style="margin: 0; font-size: 12px; color: #9CA3AF;">
                This is an automated report from <strong style="color: #f97316;">GooCampus HR Portal</strong>.
                Generated on {datetime.now().strftime('%d %b %Y at %I:%M %p')}.
            </p>
        </div>
    </div>
    '''

    logging.info(f"[EMAIL DEBUG] emp={employee_id} stats={stats} rows_html_count={len(rows_html)} html_len={len(html_body)}")

    subject = f"Attendance Report — {month_name} {year} | {emp['name']}"
    success = send_email(
        to_list=[emp['email']],
        subject=subject,
        html_body=html_body,
        cc_list=cc_list if cc_list else None
    )

    return success


@app.route('/admin/send-attendance-report', methods=['POST'])
@admin_required
def send_attendance_report():
    """Email an individual employee their monthly attendance report."""
    employee_id = request.form.get('employee_id', type=int)
    month = request.form.get('month', type=int)
    year = request.form.get('year', type=int)

    if not employee_id or not month or not year:
        flash('Missing parameters for attendance report.', 'error')
        return redirect(request.referrer or url_for('time_log'))

    success = _build_and_send_attendance_report(employee_id, month, year)
    if success:
        flash('Attendance report sent successfully.', 'success')
    else:
        flash('Failed to send report. Check email configuration or employee email.', 'error')

    return redirect(url_for('time_log', month=month, year=year))


@app.route('/admin/send-all-attendance-reports', methods=['POST'])
@admin_required
def send_all_attendance_reports():
    """Send attendance reports to ALL employees who have attendance data for the month."""
    from flask import jsonify
    import calendar as cal_mod

    month = request.form.get('month', type=int)
    year = request.form.get('year', type=int)

    if not month or not year:
        return jsonify({'status': 'error', 'message': 'Missing month/year for bulk report.'}), 400

    days_in_month = cal_mod.monthrange(year, month)[1]
    date_from = f"{year}-{month:02d}-01"
    date_to = f"{year}-{month:02d}-{days_in_month:02d}"

    conn = get_db()
    emp_rows = conn.execute(
        "SELECT DISTINCT e.id, e.name "
        "FROM employees e "
        "JOIN attendance_logs a ON a.employee_id = e.id "
        "WHERE e.is_active = 1 "
        "AND a.attendance_date >= ? AND a.attendance_date <= ? "
        "ORDER BY e.name",
        (date_from, date_to)
    ).fetchall()
    conn.close()

    sent = 0
    failed = 0
    for emp_row in emp_rows:
        try:
            success = _build_and_send_attendance_report(emp_row['id'], month, year)
            if success:
                sent += 1
            else:
                failed += 1
        except Exception as e:
            logging.error(f"Bulk send failed for employee {emp_row['id']}: {e}")
            failed += 1

    # Log the bulk send
    try:
        log_conn = get_db()
        log_conn.execute(
            "INSERT INTO report_send_log (send_type, month, year, sent_count, failed_count) "
            "VALUES (?, ?, ?, ?, ?)",
            ('bulk', month, year, sent, failed)
        )
        log_conn.commit()
        log_conn.close()
    except Exception as log_err:
        logging.error(f"Failed to log bulk send: {log_err}")

    if sent > 0 and failed == 0:
        return jsonify({
            'status': 'success',
            'message': f'Attendance reports sent successfully to all {sent} employees.',
            'sent': sent, 'failed': failed,
            'sent_at': datetime.now().strftime('%d %b %Y, %I:%M %p')
        })
    elif sent > 0 and failed > 0:
        return jsonify({
            'status': 'partial',
            'message': f'Sent to {sent} employee(s). Failed for {failed} employee(s).',
            'sent': sent, 'failed': failed,
            'sent_at': datetime.now().strftime('%d %b %Y, %I:%M %p')
        })
    elif failed > 0:
        return jsonify({
            'status': 'error',
            'message': f'Failed to send to {failed} employee(s). Check email configuration.',
            'sent': sent, 'failed': failed
        }), 500
    else:
        return jsonify({
            'status': 'warning',
            'message': 'No employees found with attendance data for this month.',
            'sent': 0, 'failed': 0
        })


