@app.route('/api/predictor/import', methods=['POST'])
@admin_required
def predictor_import():
    """Manually trigger MBBS cutoff data import from JSON."""
    try:
        conn = get_db()
        # Ensure table exists
        conn.execute('''CREATE TABLE IF NOT EXISTS mbbs_cutoffs (
            id SERIAL PRIMARY KEY,
            year INTEGER NOT NULL,
            institute_name TEXT NOT NULL,
            quota TEXT DEFAULT '',
            category TEXT DEFAULT '',
            course TEXT DEFAULT 'MBBS',
            fees NUMERIC(12,2) DEFAULT 0,
            counselling_authority TEXT DEFAULT '',
            counselling_body TEXT DEFAULT '',
            round1_rank INTEGER,
            round2_rank INTEGER,
            round3_rank INTEGER,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )''')
        conn.commit()

        existing = conn.execute("SELECT COUNT(*) as c FROM mbbs_cutoffs").fetchone()['c']
        if existing > 0:
            conn.execute("DELETE FROM mbbs_cutoffs")
            conn.commit()

        import json as _json
        json_path = os.path.join(os.path.dirname(__file__), 'mbbs_cutoff_data.json')
        if not os.path.exists(json_path):
            conn.close()
            return jsonify({'success': False, 'error': 'mbbs_cutoff_data.json not found on server'}), 404

        with open(json_path, 'r') as f:
            rows = _json.load(f)

        all_tuples = [tuple(r) for r in rows]
        insert_sql = '''INSERT INTO mbbs_cutoffs
            (year, institute_name, quota, category, course, fees,
             counselling_authority, counselling_body,
             round1_rank, round2_rank, round3_rank)
            VALUES (?,?,?,?,?,?,?,?,?,?,?)'''
        conn.execute_batch(insert_sql, all_tuples, page_size=500)
        conn.commit()
        conn.close()
        logging.info(f"Manual import: {len(all_tuples)} MBBS cutoff rows imported")
        return jsonify({'success': True, 'imported': len(all_tuples)})
    except Exception as e:
        logging.error(f"predictor_import: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/predictor/filters')
def predictor_filters():
    """Return dynamic filter options based on selected authority + year. Accessible by admin and partners."""
    if not session.get('user_id'):
        return jsonify({'error': 'Login required'}), 401
    if not session.get('is_partner'):
        # Admin check
        conn_check = get_db()
        u = conn_check.execute('SELECT is_admin FROM employees WHERE id = ?', (session['user_id'],)).fetchone()
        conn_check.close()
        if not u or u['is_admin'] != 1:
            return jsonify({'error': 'Access denied'}), 403
    conn = get_db()
    authority = request.args.get('authority', '').strip()
    year = request.args.get('year', '').strip()

    conditions = []
    params = []
    if authority:
        conditions.append("counselling_authority = ?")
        params.append(authority)
    if year:
        conditions.append("year = ?")
        params.append(int(year))

    where = "WHERE " + " AND ".join(conditions) if conditions else ""

    quotas = conn.execute(
        f"SELECT DISTINCT quota FROM mbbs_cutoffs {where} ORDER BY quota", params
    ).fetchall()
    categories = conn.execute(
        f"SELECT DISTINCT category FROM mbbs_cutoffs {where} ORDER BY category", params
    ).fetchall()
    institutes = conn.execute(
        f"SELECT DISTINCT institute_name FROM mbbs_cutoffs {where} ORDER BY institute_name", params
    ).fetchall()
    conn.close()

    return jsonify({
        'quotas': [q['quota'] for q in quotas],
        'categories': [c['category'] for c in categories],
        'institutes': [i['institute_name'] for i in institutes],
    })


@app.route('/api/predictor/search')
def predictor_search():
    """Search cut-off data with filters. Returns JSON. Accessible by admin and partners."""
    if not session.get('user_id'):
        return jsonify({'error': 'Login required'}), 401
    if not session.get('is_partner'):
        conn_check = get_db()
        u = conn_check.execute('SELECT is_admin FROM employees WHERE id = ?', (session['user_id'],)).fetchone()
        conn_check.close()
        if not u or u['is_admin'] != 1:
            return jsonify({'error': 'Access denied'}), 403
    conn = get_db()
    authority = request.args.get('authority', '').strip()
    year = request.args.get('year', '').strip()
    quota = request.args.get('quota', '').strip()
    category = request.args.get('category', '').strip()
    institute = request.args.get('institute', '').strip()
    rank = request.args.get('rank', '').strip()
    fee_min = request.args.get('fee_min', '').strip()
    fee_max = request.args.get('fee_max', '').strip()
    page = int(request.args.get('page', 1))
    per_page = 50

    conditions = []
    params = []

    if authority:
        conditions.append("counselling_authority = ?")
        params.append(authority)
    if year:
        conditions.append("year = ?")
        params.append(int(year))
    if quota:
        conditions.append("quota = ?")
        params.append(quota)
    if category:
        conditions.append("category = ?")
        params.append(category)
    if institute:
        conditions.append("LOWER(institute_name) LIKE LOWER(?)")
        params.append(f"%{institute}%")
    if rank:
        # Show colleges where user's rank is <= any round's cutoff rank
        rank_val = int(rank)
        conditions.append("(round1_rank >= ? OR round2_rank >= ? OR round3_rank >= ?)")
        params.extend([rank_val, rank_val, rank_val])
    if fee_min:
        conditions.append("fees >= ?")
        params.append(float(fee_min))
    if fee_max:
        conditions.append("fees <= ?")
        params.append(float(fee_max))

    where = "WHERE " + " AND ".join(conditions) if conditions else ""

    # Count total
    count_params = list(params)
    total = conn.execute(f"SELECT COUNT(*) as c FROM mbbs_cutoffs {where}", count_params).fetchone()['c']

    # Fetch page
    offset = (page - 1) * per_page
    query_params = list(params)
    query_params.extend([per_page, offset])
    rows = conn.execute(f'''
        SELECT institute_name, quota, category, fees, counselling_authority,
               counselling_body, round1_rank, round2_rank, round3_rank, year
        FROM mbbs_cutoffs {where}
        ORDER BY round1_rank ASC NULLS LAST, institute_name ASC
        LIMIT ? OFFSET ?
    ''', query_params).fetchall()

    # Build slug lookup for linking to college profiles
    inst_names = list(set(r['institute_name'] for r in rows))
    slug_map = {}
    if inst_names:
        for name in inst_names:
            slug_row = conn.execute(
                "SELECT slug FROM colleges WHERE name = ? LIMIT 1", (name,)
            ).fetchone()
            if slug_row:
                slug_map[name] = slug_row['slug']

    conn.close()

    results = []
    for r in rows:
        results.append({
            'institute': r['institute_name'],
            'slug': slug_map.get(r['institute_name'], ''),
            'quota': r['quota'],
            'category': r['category'],
            'fees': float(r['fees'] or 0),
            'authority': r['counselling_authority'],
            'body': r['counselling_body'],
            'r1': r['round1_rank'],
            'r2': r['round2_rank'],
            'r3': r['round3_rank'],
            'year': r['year'],
        })

    return jsonify({
        'results': results,
        'total': total,
        'page': page,
        'per_page': per_page,
        'total_pages': (total + per_page - 1) // per_page,
    })


# ── College List Page ──
@app.route('/colleges')
@admin_required
def colleges_list():
    conn = get_db()
    category = request.args.get('category', 'all')
    search = request.args.get('search', '').strip()
    country = request.args.get('country', '')
    state_filter = request.args.get('state', '')
    course_filter = request.args.get('course', '').strip()
    fee_min = request.args.get('fee_min', '')
    fee_max = request.args.get('fee_max', '')

    query = "SELECT * FROM colleges WHERE is_active = TRUE"
    params = []

    if category == 'indian':
        query += " AND category = 'indian'"
    elif category == 'international':
        query += " AND category = 'international'"

    if country:
        query += " AND country = ?"
        params.append(country)

    if state_filter:
        query += " AND state_or_region = ?"
        params.append(state_filter)

    if search:
        query += " AND (LOWER(name) LIKE ? OR LOWER(city) LIKE ?)"
        params.extend([f'%{search.lower()}%', f'%{search.lower()}%'])

    # Fee range filtering is done post-query using live conversion
    query += " ORDER BY is_featured DESC, name ASC"
    colleges = conn.execute(query, params).fetchall()

    # Get unique countries for filter (international only)
    countries = conn.execute(
        "SELECT DISTINCT country FROM colleges WHERE is_active = TRUE AND category = 'international' ORDER BY country"
    ).fetchall()

    # Get unique states for Indian colleges filter
    states = conn.execute(
        "SELECT DISTINCT state_or_region FROM colleges WHERE is_active = TRUE AND category = 'indian' AND state_or_region != '' ORDER BY state_or_region"
    ).fetchall()

    # Get unique courses for Indian filter
    courses_list = conn.execute(
        "SELECT DISTINCT cc.course_name FROM college_courses cc JOIN colleges c ON cc.college_id = c.id WHERE c.is_active = TRUE AND c.category = 'indian' AND cc.is_active = TRUE ORDER BY cc.course_name"
    ).fetchall()

    # Get course count per college
    course_counts = {}
    for c in colleges:
        cnt = conn.execute(
            "SELECT COUNT(*) as cnt FROM college_courses WHERE college_id = ? AND is_active = TRUE",
            (c['id'],)
        ).fetchone()
        course_counts[c['id']] = cnt['cnt'] if cnt else 0

    # Filter by course (post-query since it requires join)
    if course_filter:
        college_ids_with_course = conn.execute(
            "SELECT DISTINCT cc.college_id FROM college_courses cc WHERE cc.is_active = TRUE AND LOWER(cc.course_name) LIKE ?",
            (f'%{course_filter.lower()}%',)
        ).fetchall()
        valid_ids = {r['college_id'] for r in college_ids_with_course}
        colleges = [c for c in colleges if c['id'] in valid_ids]

    # Get exchange rates for INR display
    rates = _get_exchange_rates()

    # Compute live full_package_inr_lakhs for international colleges
    # Sum all fee structure row totals (each year/sem is its own row), convert to INR
    live_package = {}
    for c in colleges:
        if c['category'] == 'international' and c['currency'] and c['currency'] != 'INR':
            fee_sum = conn.execute(
                """SELECT COALESCE(SUM(fs.total), 0) as grand_total
                   FROM college_fee_structure fs
                   JOIN college_courses cc ON fs.course_id = cc.id
                   WHERE cc.college_id = ? AND cc.is_active = TRUE""",
                (c['id'],)
            ).fetchone()
            total_foreign = float(fee_sum['grand_total'] or 0)
            if total_foreign > 0:
                total_inr = _to_inr(total_foreign, c['currency'], rates)
                live_package[c['id']] = round(total_inr / 100000, 2)
            else:
                live_package[c['id']] = float(c['full_package_inr_lakhs'] or 0)
        else:
            live_package[c['id']] = float(c['full_package_inr_lakhs'] or 0)

    # Apply fee range filter on live computed values
    if fee_min:
        try:
            mn = float(fee_min)
            colleges = [c for c in colleges if live_package.get(c['id'], 0) >= mn]
        except ValueError:
            pass
    if fee_max:
        try:
            mx = float(fee_max)
            colleges = [c for c in colleges if live_package.get(c['id'], 0) <= mx]
        except ValueError:
            pass

    # All college names for autocomplete
    all_names = conn.execute(
        "SELECT name FROM colleges WHERE is_active = TRUE ORDER BY name"
    ).fetchall()

    conn.close()
    return render_template('colleges_list.html',
        colleges=colleges,
        countries=[c['country'] for c in countries],
        states=[s['state_or_region'] for s in states],
        courses_list=[c['course_name'] for c in courses_list],
        all_college_names=[n['name'] for n in all_names],
        course_counts=course_counts,
        live_package=live_package,
        category=category,
        search=search,
        country_filter=country,
        state_filter=state_filter,
        course_filter=course_filter,
        fee_min=fee_min,
        fee_max=fee_max,
        rates=rates,
        to_inr=_to_inr,
                    active_section='colleges')


# ── College Profile Page ──
@app.route('/colleges/<slug>')
@admin_required
def college_profile(slug):
    conn = get_db()
    college = conn.execute("SELECT * FROM colleges WHERE slug = ?", (slug,)).fetchone()
    if not college:
        conn.close()
        flash("College not found.", "danger")
        return redirect('/colleges')

    courses = conn.execute(
        "SELECT * FROM college_courses WHERE college_id = ? AND is_active = TRUE ORDER BY course_name",
        (college['id'],)
    ).fetchall()

    # Get fee structure for each course
    fees_by_course = {}
    for course in courses:
        fees = conn.execute(
            "SELECT * FROM college_fee_structure WHERE course_id = ? ORDER BY year_label, semester",
            (course['id'],)
        ).fetchall()
        fees_by_course[course['id']] = fees

    rates = _get_exchange_rates()

    # Compute live full package in INR lakhs (sum all fee rows, convert to INR)
    live_package_lakhs = 0
    if college['category'] == 'international' and college['currency'] and college['currency'] != 'INR':
        total_foreign = sum(float(f['total'] or 0) for flist in fees_by_course.values() for f in flist)
        if total_foreign > 0:
            total_inr = _to_inr(total_foreign, college['currency'], rates)
            live_package_lakhs = round(total_inr / 100000, 2)
        else:
            live_package_lakhs = float(college['full_package_inr_lakhs'] or 0)
    else:
        live_package_lakhs = float(college['full_package_inr_lakhs'] or 0)

    # Fetch MBBS cut-off data for this college (matching by name)
    cutoffs = []
    cutoff_years = []
    try:
        cutoff_rows = conn.execute(
            "SELECT * FROM mbbs_cutoffs WHERE institute_name = ? ORDER BY year DESC, quota, category",
            (college['name'],)
        ).fetchall()
        cutoffs = [dict(r) for r in cutoff_rows]
        cutoff_years = sorted(set(c['year'] for c in cutoffs), reverse=True)
    except Exception:
        pass

    conn.close()
    return render_template('college_profile.html',
        college=college,
        courses=courses,
        fees_by_course=fees_by_course,
        live_package_lakhs=live_package_lakhs,
        rates=rates,
        to_inr=_to_inr,
        currency_sym=_currency_sym,
        cutoffs=cutoffs,
        cutoff_years=cutoff_years,
                    active_section='colleges')


