# ═══════════════════════════════════════════════════════════════════════════════
# NEET PG 2025 CUT-OFF LANDING PAGE
# ═══════════════════════════════════════════════════════════════════════════════

def ensure_neetpg_tables():
    """Create neetpg_pdfs, neetpg_leads, and neetpg_page_visits tables if they don't exist."""
    try:
        conn = get_db()
        conn.execute('''CREATE TABLE IF NOT EXISTS neetpg_pdfs (
            id SERIAL PRIMARY KEY,
            title TEXT NOT NULL,
            category TEXT NOT NULL DEFAULT 'neetpg',
            specialty TEXT NOT NULL,
            file_name TEXT NOT NULL,
            file_size INTEGER DEFAULT 0,
            file_data BYTEA,
            upload_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            download_count INTEGER DEFAULT 0,
            is_active INTEGER DEFAULT 1
        )''')
        conn.execute('''CREATE TABLE IF NOT EXISTS neetpg_leads (
            id SERIAL PRIMARY KEY,
            name TEXT NOT NULL,
            whatsapp TEXT,
            email TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            source TEXT DEFAULT 'neetpg_landing'
        )''')
        conn.execute('''CREATE TABLE IF NOT EXISTS neetpg_page_visits (
            id SERIAL PRIMARY KEY,
            visited_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            ip_hash TEXT,
            user_agent TEXT
        )''')
        conn.execute('''CREATE TABLE IF NOT EXISTS neetpg_requests (
            id SERIAL PRIMARY KEY,
            phone TEXT NOT NULL,
            name TEXT NOT NULL,
            category TEXT NOT NULL DEFAULT 'neetpg',
            state TEXT,
            message TEXT NOT NULL,
            status TEXT DEFAULT 'pending',
            admin_note TEXT,
            notified INTEGER DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            completed_at TIMESTAMP
        )''')
        conn.commit()
        # Migration helper: each ALTER needs its own commit/rollback for PostgreSQL
        migrations = [
            "ALTER TABLE ops_call_notes ADD COLUMN contacted_status TEXT DEFAULT 'Yes'",
            "ALTER TABLE ops_call_notes ADD COLUMN contact_type TEXT DEFAULT 'Call'",
            "ALTER TABLE neetpg_leads ADD COLUMN email TEXT",
            "ALTER TABLE neetpg_leads ALTER COLUMN whatsapp DROP NOT NULL",
            "ALTER TABLE neetpg_pdfs ADD COLUMN state TEXT DEFAULT 'All India/MCC'",
            "ALTER TABLE neetpg_pdfs ADD COLUMN is_published INTEGER DEFAULT 0",
            "ALTER TABLE neetpg_pdfs ADD COLUMN published_at TIMESTAMP",
            "ALTER TABLE neetpg_pdfs ADD COLUMN auto_schedule INTEGER DEFAULT 1",
            "ALTER TABLE neetpg_requests ADD COLUMN fulfilled_pdf_id INTEGER",
            "ALTER TABLE neetpg_requests ADD COLUMN fulfilled_pdf_title TEXT",
        ]
        for sql in migrations:
            try:
                conn.execute(sql)
                conn.commit()
            except Exception:
                conn.rollback()
        # One-time: backdate published_at on all PDFs published before May 13 8:30 AM IST
        # to remove NEW badge. PDFs published after 8:45 AM IST onwards keep NEW badge.
        # 8:30 AM IST = 3:00 AM UTC on May 13.
        try:
            conn.execute(
                "UPDATE neetpg_pdfs SET published_at = '2026-05-01 00:00:00' "
                "WHERE is_published = 1 AND published_at <= '2026-05-13 03:00:00'"
            )
            conn.commit()
        except Exception:
            conn.rollback()
        conn.close()
    except Exception as e:
        logging.error(f"ensure_neetpg_tables: {e}")

ensure_neetpg_tables()


