@app.route('/admin/neetpg-leads/export')
@login_required
def neetpg_export_leads():
    user = get_user()
    if not user.get('is_admin'):
        flash('Admin access required', 'error')
        return redirect(url_for('dashboard'))
    conn = get_db()
    leads = conn.execute("SELECT name, whatsapp, email, source, created_at FROM neetpg_leads ORDER BY created_at DESC").fetchall()
    conn.close()
    wb = Workbook()
    ws = wb.active
    ws.title = "NEET PG Leads"
    headers = ['Name', 'WhatsApp', 'Email', 'Source', 'Captured At']
    header_fill = PatternFill(start_color='1B2A4A', end_color='1B2A4A', fill_type='solid')
    header_font = Font(bold=True, color='FFFFFF')
    for col, h in enumerate(headers, 1):
        cell = ws.cell(row=1, column=col, value=h)
        cell.fill = header_fill
        cell.font = header_font
    for row, lead in enumerate(leads, 2):
        ws.cell(row=row, column=1, value=lead['name'])
        ws.cell(row=row, column=2, value=lead['whatsapp'] or '')
        ws.cell(row=row, column=3, value=lead['email'] or '')
        ws.cell(row=row, column=4, value=lead['source'] or 'whatsapp')
        ws.cell(row=row, column=5, value=str(lead['created_at']))
    ws.column_dimensions['A'].width = 25
    ws.column_dimensions['B'].width = 15
    ws.column_dimensions['C'].width = 30
    ws.column_dimensions['D'].width = 12
    ws.column_dimensions['E'].width = 22
    output = BytesIO()
    wb.save(output)
    output.seek(0)
    return send_file(output, download_name='neetpg_leads.xlsx', as_attachment=True,
                     mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')


# ── Auto-publish scheduler (10 AM + 5 PM IST daily, FIFO) ──
# Slots: 10:00 AM IST and 5:00 PM IST — one PDF per slot, oldest first.
# On startup we catch up on any missed slots for today so deploys/restarts
# don't cause skipped publishes.

def neetpg_auto_publish():
    """Publish the next draft PDF that has auto_schedule=1 (FIFO: oldest upload first)."""
    try:
        conn = get_db()
        draft = conn.execute(
            "SELECT id, title, state FROM neetpg_pdfs WHERE is_published = 0 AND is_active = 1 AND auto_schedule = 1 ORDER BY upload_date ASC LIMIT 1"
        ).fetchone()
        if draft:
            conn.execute(
                "UPDATE neetpg_pdfs SET is_published = 1, published_at = CURRENT_TIMESTAMP WHERE id = ?",
                (draft['id'],)
            )
            conn.commit()
            print(f"[AUTO_PUBLISH] Published PDF id={draft['id']} title='{draft['title']}' — triggering WA notify", flush=True)
            # Send WhatsApp notification to all leads
            neetpg_wa_notify_leads(draft['title'], draft.get('state', ''))
        else:
            print("[AUTO_PUBLISH] No drafts to publish", flush=True)
        conn.close()
    except Exception as e:
        logging.error(f"neetpg_auto_publish error: {e}")


def neetpg_catchup_publish():
    """On startup, publish drafts for any slots missed today.

    Approach: count how many 10 AM / 1 PM / 5 PM slots have passed today in IST,
    then count how many PDFs were already published today (IST date).
    If published < passed_slots, publish the difference (FIFO, max 3/day).
    Uses IST-based date comparison via AT TIME ZONE to avoid UTC mismatch.
    """
    try:
        import pytz
        ist = pytz.timezone('Asia/Kolkata')
        now_ist = datetime.now(ist)

        # How many slots have passed today?
        slots_passed = 0
        if now_ist.hour >= 10:
            slots_passed += 1
        if now_ist.hour >= 13:
            slots_passed += 1
        if now_ist.hour >= 17:
            slots_passed += 1

        if slots_passed == 0:
            logging.info("Catchup: no slots passed yet today, nothing to do")
            return

        # Count PDFs published today (IST date)
        today_ist_str = now_ist.strftime('%Y-%m-%d')
        conn = get_db()
        published_today = conn.execute(
            "SELECT COUNT(*) as c FROM neetpg_pdfs WHERE is_published = 1 "
            "AND (published_at AT TIME ZONE 'UTC' AT TIME ZONE 'Asia/Kolkata')::date = ?::date",
            (today_ist_str,)
        ).fetchone()['c']

        need = slots_passed - published_today
        if need <= 0:
            logging.info(f"Catchup: {slots_passed} slot(s) passed, {published_today} already published today — no catchup needed")
            conn.close()
            return

        # Cap at 3 per day max
        need = min(need, 3)
        drafts = conn.execute(
            "SELECT id, title, state FROM neetpg_pdfs WHERE is_published = 0 AND is_active = 1 AND auto_schedule = 1 ORDER BY upload_date ASC LIMIT ?",
            (need,)
        ).fetchall()
        for draft in drafts:
            conn.execute(
                "UPDATE neetpg_pdfs SET is_published = 1, published_at = CURRENT_TIMESTAMP WHERE id = ?",
                (draft['id'],)
            )
            logging.info(f"Catchup-published NEET PG PDF id={draft['id']} title={draft['title']}")
            # Send WhatsApp notification to all leads
            neetpg_wa_notify_leads(draft['title'], draft.get('state', ''))
        if drafts:
            conn.commit()
        logging.info(f"Catchup: {slots_passed} slot(s) passed, {published_today} published today, catchup-published {len(drafts)}")
        conn.close()
    except Exception as e:
        logging.error(f"neetpg_catchup_publish error: {e}")


def start_neetpg_scheduler():
    """Start background scheduler for auto-publishing PDFs at 10 AM, 1 PM and 5 PM IST.

    Also runs a one-time catchup to handle any slots missed due to app restarts.
    """
    try:
        from apscheduler.schedulers.background import BackgroundScheduler
        from apscheduler.triggers.cron import CronTrigger
        import pytz
        ist = pytz.timezone('Asia/Kolkata')
        scheduler = BackgroundScheduler()
        # 10:00 AM IST daily
        scheduler.add_job(neetpg_auto_publish, CronTrigger(hour=10, minute=0, timezone=ist), id='neetpg_publish_morning')
        # 1:00 PM IST daily
        scheduler.add_job(neetpg_auto_publish, CronTrigger(hour=13, minute=0, timezone=ist), id='neetpg_publish_afternoon')
        # 5:00 PM IST daily
        scheduler.add_job(neetpg_auto_publish, CronTrigger(hour=17, minute=0, timezone=ist), id='neetpg_publish_evening')
        scheduler.start()
        logging.info("NEET PG auto-publish scheduler started (10 AM + 1 PM + 5 PM IST)")
        # Run catchup for missed slots after restarts/deploys
        neetpg_catchup_publish()
    except ImportError:
        logging.warning("APScheduler not installed. Auto-publish disabled. pip install APScheduler pytz")
    except Exception as e:
        logging.error(f"Scheduler start failed: {e}")


# Start scheduler on app boot (only in production, not in reloader child)
if os.environ.get('WERKZEUG_RUN_MAIN') != 'true' or os.environ.get('DATABASE_URL'):
    start_neetpg_scheduler()


